@app.route("/plataforma/empresa/<int:id_>")
def plataforma_empresa(id_):
    """A pagina de UMA empresa, para o dono (a §7 da segunda ronda): as
    contas com a ultima entrada, os convites por usar (anular, gerar de
    novo), os alertas e se o e-mail sai, o perfil, as propostas em curso,
    as leituras do modelo, e os dois gestos do suporte -- ver como a
    empresa, so para ler, e suspender. O trabalho dela (as propostas, as
    notas, os contactos) nao se mostra: para isso e o «ver como», que
    fica registado."""
    e = _empresa_ou_404(id_)
    with liga() as c:
        contas_ = contas.utilizadores(c, id_)
        sessoes = dict(c.execute(
            "SELECT utilizador_id, COUNT(*) FROM sessoes WHERE expira > ? "
            "GROUP BY utilizador_id",
            (datetime.now().strftime("%Y-%m-%d %H:%M:%S"),)).fetchall())
        convites = contas.convites_por_usar(c, id_)
    agora = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    # o que o «Suspender» fecha, para a confirmação o dizer (V4 P5)
    fecha_contas = sum(1 for u in contas_ if not u["dono"])
    fecha_sessoes = sum(sessoes.get(u["id"], 0) for u in contas_ if not u["dono"])
    linhas_contas = "".join(
        "<tr>%s%s%s%s%s</tr>" % (
            _celula_da_tabela("Utilizador", html.escape(u["email"]) + (
                " <span class='mg-tag %s'>suspensa</span>" % tom("mau")
                if u["suspensa"] else "")),
            _celula_da_tabela("Papel", html.escape(papel_no_ecra(u["papel"])
                                        + (" · dono" if u["dono"] else ""))),
            _celula_da_tabela("Última entrada", html.escape(
                data_hora_pt((u["ultimo_acesso"] or "")[:16], "nunca"))),
            _celula_da_tabela("Sessões abertas", "%d" % sessoes.get(u["id"], 0), "mg-num"),
            _celula_da_tabela("", "<div class='mg-row' style='gap:6px;flex-wrap:wrap'>%s</div>"
                              % "".join(_gestos_do_suporte(u))))
        for u in contas_)
    bloco_contas = cartao(
        "Contas", ("<table class='mg-table tab-plataforma'><thead><tr><th>Utilizador</th>"
                   "<th>Papel</th><th>Última entrada</th><th>Sessões abertas</th>"
                   "<th><span class='so-leitor'>Acções</span></th></tr></thead>"
                   "<tbody>%s</tbody></table>" % linhas_contas)
        if contas_ else "<p class='nota'>Ainda ninguém criou conta: está à espera "
                        "de um convite.</p>", id_="contas")
    linhas_convites = "".join(
        "<tr>%s%s%s%s%s</tr>" % (
            _celula_da_tabela("Para", html.escape(cv["email"] or "sem endereço")),
            _celula_da_tabela("Papel", html.escape(papel_no_ecra(cv["papel"]))),
            _celula_da_tabela("Criado", html.escape(data_hora_pt(cv["criado_em"][:16]))),
            _celula_da_tabela("Vale até", ("<span class='mg-tag %s'>acabou</span>" % tom("mau")
                                 if cv["expira"] <= agora else "")
                    + html.escape(data_hora_pt(cv["expira"][:16]))),
            _celula_da_tabela("", "<div class='mg-row' style='gap:6px;flex-wrap:wrap'>%s%s</div>"
                    % (accao("/plataforma/convites/%d/renovar" % cv["id"], "gerar de novo",
                             "mini", rotulo="Gerar uma ligação nova para este convite"),
                       accao("/plataforma/convites/%d/anular" % cv["id"], "anular",
                             "mini cuidado", "Anular este convite? A ligação deixa de servir.",
                             rotulo=("Anular o convite para %s" % cv["email"] if cv["email"]
                                     else "Anular o convite de %s criado a %s"
                                     % (papel_no_ecra(cv["papel"]).lower(),
                                        data_pt((cv["criado_em"] or "")[:10])))))))
        for cv in convites)
    bloco_plano = _cartao_do_plano(id_)
    bloco_convites = cartao(
        "Convites por usar",
        ("<table class='mg-table tab-plataforma'><thead><tr><th>Para</th><th>Papel</th>"
         "<th>Criado</th><th>Vale até</th><th><span class='so-leitor'>Acções</span></th>"
         "</tr></thead><tbody>%s</tbody></table>" % linhas_convites
         if convites else "<p class='nota'>Nenhum.</p>")
        + "<form class='form-email' method='post' action='/plataforma/empresa/%d/convite' "
          "style='margin-top:16px'><label>Para <span class='nota'>(opcional)</span>"
          "<input class='mg-field__input' type='email' name='email' "
          "autocomplete='off' placeholder='nome@empresa.pt'></label>"
          "<label>Papel"
          "<select class='mg-field__input' name='papel'>"
          "<option value='admin'>Gestor</option><option value='tester'>Utilizador"
          "</option></select></label><button type='submit' class='mg-btn mg-btn--secondary'>"
          "Criar convite</button></form>" % id_,
        meta="A ligação só se vê ao criá-la: «gerar de novo» anula a antiga e mostra "
             "uma nova, para reenviar.", id_="convites")
    # Sem alertas ligados não sai nada, e a página dizia «o e-mail sai»
    # (3.ª ronda, G30)
    envio = ("não sai: nenhum alerta ligado" if not e["alertas"]
             else "sai para %s" % html.escape(e["para"]) if not e["email"]
             else "não sai: %s" % html.escape(e["email"]))
    with com_empresa(id_):
        envios = envios_dos_alertas(limite=10)
    bloco_alertas = cartao(
        "Alertas e e-mail",
        "<p>%s</p><p class='nota'>O resumo por e-mail %s.</p>%s"
        % ("%d alerta%s ligado%s: %s" % (
            len(e["alertas"]), "" if len(e["alertas"]) == 1 else "s",
            "" if len(e["alertas"]) == 1 else "s",
            html.escape(", ".join(e["alertas"])))
           if e["alertas"] else "Nenhum alerta ligado.", envio,
           envios_html(envios) if envios else
           "<p class='nota'>Ainda não saiu nenhum envio.</p>"))
    bloco_perfil = cartao(
        "Perfil da empresa",
        "<p>%s</p>" % (e["perfil"] or "Por definir: a empresa vê os concursos todos."))
    suspensa = e["suspensa"]
    accoes = (accao("/plataforma/empresa/%d/ver-como" % id_,
                    icone("ver") + " Ver como a empresa, só leitura", "bt",
                    rotulo="Ver a aplicação como a empresa %s, só para ler" % e["nome"])
              + accao("/plataforma/empresa/%d/%s" % (id_, "reactivar" if suspensa
                                                       else "suspender"),
                      "Reactivar" if suspensa else "Suspender",
                      "bt" if suspensa else "bt cuidado",
                      "" if suspensa else
                      "Suspender %s? %s deixa%s de entrar, e %s. A verificação "
                      "deixa de lhe mandar alertas. Nada se apaga."
                      % (e["nome"], plural(fecha_contas, "conta"),
                         "" if fecha_contas == 1 else "m",
                         "não há sessões abertas" if not fecha_sessoes else
                         "quem está dentro vê já «Acesso suspenso»")))
    stats = "<div class='mg-stats'>%s%s%s%s</div>" % (
        kpi("Contas", "%d" % e["contas"],
            "última entrada %s" % ha_quanto(e["ultima"])),
        kpi("Propostas em curso", "%d" % e["activas"]),
        kpi("Leituras do modelo hoje", "%d / %d" % (e["leituras_hoje"], e["tecto"]),
            "tecto por dia; %d este mês%s" % (
                e["leituras_mes"],
                " de %d" % e["tecto_mes"] if e["tecto_mes"] else "")),
        kpi("Alertas ligados", "%d" % len(e["alertas"]),
            "o e-mail não sai (suspensa)" if suspensa else
            "o e-mail não sai: nenhum ligado" if not e["alertas"] else
            "o e-mail sai" if not e["email"] else "o e-mail não sai"))
    corpo = ("<div class='larg' style='display:flex;flex-direction:column;gap:18px'>"
             "%s%s%s%s%s%s%s%s%s%s</div>"
             % ("<div class='mg-alert mg-alert--danger'>Suspensa: as contas não entram "
                "e não recebe alertas.</div>" if suspensa else "",
                stats, _cartao_da_nota(id_), bloco_plano, bloco_contas, bloco_convites,
                _cartao_da_actividade(id_) + _cartao_do_uso(id_), bloco_alertas,
                bloco_perfil,
                _cartao_de_apagar(e, fecha_contas, len(convites),
                                  any(u["dono"] for u in contas_))))
    return envolver(
        "configuracoes", e["nome"], "", corpo, titulo_aba="%s · Plataforma" % e["nome"],
        cabeca=cabecalho_de_pagina(
            html.escape(e["nome"]),
            "Empresa n.º %d%s · %s" % (
                id_, (" · NIF %s" % html.escape(e["nif"])) if e["nif"] else "",
                "chegou a %s" % html.escape(data_pt(e["desde"])) if e["desde"]
                else "sem data de chegada"),
            [("Plataforma", "/plataforma"), (e["nome"], "")], accoes))


def _cartao_do_plano(id_):
    """O plano da empresa, para o dono o ver e mudar (L2.1 do plano de
    Outubro, com os planos de 1/10/2026). Sem plano, avisa: a empresa nao
    tem limites ate o dono o por."""
    with liga() as c:
        p = contas.plano_da_empresa(c, id_)
        livres = contas.lugares_livres(c, id_)
    if p:
        nome = contas.PLANOS[p["plano"]][0]
        frase = ("<p>%s, %s%s, desde %s. %s</p>" % (
            nome, p["periodo"], " · fundador" if p["fundador"] else "",
            data_pt(p["desde"] or ""),
            "Sem limite de utilizadores." if livres is None else
            "%s de %s." % (plural(livres, "lugar livre", "lugares livres"),
                           plural(p["utilizadores"], "utilizador", "utilizadores"))))
    else:
        frase = ("<div class='mg-alert mg-alert--warning'>Esta empresa não tem "
                 "plano: não tem limite de utilizadores nem a sessão única do "
                 "Solo. Escolha-o aqui.</div>")
    # sem plano, o selector não mostra o Solo como se fosse o escolhido
    # (4.ª ronda)
    opcoes = ("" if p else "<option value='' selected disabled>— escolha —</option>") + "".join(
        "<option value='%s'%s>%s</option>" % (
            k, " selected" if p and p["plano"] == k else "", html.escape(v[0]))
        for k, v in contas.PLANOS.items())
    periodos = "".join("<option value='%s'%s>%s</option>" % (
        k, " selected" if p and p["periodo"] == k else "", k)
        for k in contas.PERIODOS)
    return cartao(
        "Plano",
        frase
        + "<form class='form-email' method='post' action='/plataforma/empresa/%d/plano'>"
          "<label>Plano<select class='mg-field__input' name='plano'>%s</select></label>"
          "<label>Período<select class='mg-field__input' name='periodo'>%s</select></label>"
          "<label>Utilizadores <span class='nota'>(só no Corporate)</span>"
          "<input class='mg-field__input' type='number' name='utilizadores' min='1' "
          "max='999' value='%s'></label>"
          "<label><input type='checkbox' name='fundador' value='1'%s> Fundador</label>"
          "<button type='submit' class='mg-btn mg-btn--secondary'>Gravar o plano</button>"
          "</form>"
        % (id_, opcoes, periodos,
           p["utilizadores"] if p and p["plano"] == "corporate" and p["utilizadores"] else "",
           " checked" if p and p["fundador"] else ""),
        meta="Todos têm o mesmo; muda o número de pessoas: o Solo tem 1 e uma "
             "sessão de cada vez, o Duo 2, o Corporate o número acordado.",
        id_="plano")


@app.route("/plataforma/empresa/<int:id_>/plano", methods=["POST"])
def plataforma_gravar_plano(id_):
    """Grava o plano da empresa (L2.1). So o dono: a rota vive debaixo de
    `/plataforma`, em `ROTAS_SO_DONO`. Mudar o plano nao tira contas:
    abaixo do limite, so deixa de se poder convidar."""
    _empresa_ou_404(id_)
    f = request.form
    utilizadores = (f.get("utilizadores") or "").strip()
    # o Corporate sem número ficava sem limite nenhum (5.ª ronda)
    if (f.get("plano") or "").strip() == "corporate" and not utilizadores:
        return _volta_a("/plataforma/empresa/%d#plano" % id_,
                        "No Corporate, escreva quantos utilizadores foram acordados.",
                        erro=True)
    # [0-9] e não isdigit(): «²» é dígito para o Python e rebentava no int()
    if utilizadores and not (re.fullmatch(r"[0-9]{1,3}", utilizadores)
                             and int(utilizadores) > 0):
        return _volta_a("/plataforma/empresa/%d#plano" % id_,
                        "O número de utilizadores tem de ser de 1 a 999.", erro=True)
    try:
        with liga() as c:
            contas.gravar_plano(c, id_, (f.get("plano") or "").strip(),
                                (f.get("periodo") or "mensal").strip(),
                                bool(f.get("fundador")),
                                int(utilizadores) if utilizadores else None)
    except ValueError as erro:
        return _volta_a("/plataforma/empresa/%d#plano" % id_, str(erro), erro=True)
    registar_evento("", "plano", "mudou o plano da empresa %d para %s"
                    % (id_, f.get("plano")), quem=quem_sou() or "")
    # Descer não tira contas (é a regra); mas diz-se (4.ª ronda: um Solo
    # com duas contas gravava-se calado)
    with liga() as c:
        p = contas.plano_da_empresa(c, id_)
        n = len([u for u in contas.utilizadores(c, id_) if not u["dono"]])
    if p and p["utilizadores"] and n > p["utilizadores"]:
        return _volta_a("/plataforma/empresa/%d#plano" % id_,
                        "Plano gravado. A empresa tem %s e o plano só %s: as "
                        "contas continuam a entrar até tirar as que sobram."
                        % (plural(n, "conta"), plural(p["utilizadores"], "utilizador",
                                                       "utilizadores")), erro=True)
    return _volta_a("/plataforma/empresa/%d#plano" % id_, "Plano gravado.")


@app.route("/plataforma/empresa/<int:id_>/convite", methods=["POST"])
def plataforma_criar_convite(id_):
    """Um convite novo para a empresa, pelo dono: a empresa que chegou por
    telefone, ou o admin que saiu. A ligacao mostra-se uma vez."""
    e = _empresa_ou_404(id_)
    papel = (request.form.get("papel") or "admin").strip()
    if papel not in contas.PAPEIS:
        abort(400)
    # o endereço, opcional (G61): sem ele o convite ficava «para: sem
    # endereço», e quem o recebia não tinha o utilizador pré-preenchido
    email = (request.form.get("email") or "").strip()
    if email and not RX_EMAIL.fullmatch(email):
        return _volta_a("/plataforma/empresa/%d#convites" % id_,
                        "«%s» não é um e-mail." % corta(email, 60), erro=True)
    try:
        with liga() as c:
            codigo = contas.criar_convite(c, id_, email, papel)
    except ValueError as erro:
        # o limite do plano (L2.1): o dono muda o plano no cartão de cima.
        # A frase é a do gestor; ao dono diz-se o que ele pode fazer (4.ª ronda)
        return _volta_a("/plataforma/empresa/%d#plano" % id_,
                        str(erro).replace("Para mais, fale connosco.",
                                          "Mude o plano aqui, ou anule um convite."),
                        erro=True)
    registar_evento("", "convite", "criou um convite (%s) para a empresa %d"
                    % (papel, id_), quem=quem_sou() or "")
    return _mostrar_convite(e, codigo, papel, email)


def razao_do_correio(porque):
    """A razão de um e-mail não sair, dita a quem a lê: o que só o dono
    resolve (a palavra-passe no `email_senha.txt`, o servidor) diz-se ao
    cliente sem o ficheiro do servidor (4.ª e 5.ª rondas: os Alertas e o
    ecrã do convite mostravam-no ao gestor)."""
    if not porque or sou_dono():
        return porque
    if EMAIL_SEM_SENHA in porque or EMAIL_POR_CONFIGURAR in porque:
        return "o envio da plataforma ainda não está configurado"
    return porque


def _frase_do_envio(email, bem, porque):
    """O que o ecrã da ligação diz do e-mail do convite, antes do resto."""
    if not email:
        return ""
    if bem:
        return "O convite seguiu por e-mail para <b>%s</b>. " % html.escape(email)
    return ("<b>O e-mail para %s não saiu</b> (%s). "
            % (html.escape(email), html.escape(razao_do_correio(porque) or "sem razão")))


def _mostrar_convite(e, codigo, papel, email=""):
    ligacao = "%s/convite/%s" % (endereco_do_painel().rstrip("/"), codigo)
    bem, porque = (enviar_convite(email, ligacao, e["nome"], papel)
                   if email else (False, ""))
    return mostrar_uma_vez(
        "Convite de %s para %s" % (papel_no_ecra(papel).lower(), e["nome"]),
        _frase_do_envio(email, bem, porque)
        + "Mande esta ligação. Vale %d dias e só uma vez; <b>não se volta a "
        "ver</b> depois de sair desta página &mdash; se se perder, gere outra."
        % contas.DIAS_DE_CONVITE,
        ligacao, "Ligação do convite", "/plataforma/empresa/%d#convites" % e["id"])


# As ligações que se mostram UMA vez (o convite e o repor), guardadas
# entre o POST que as cria e o GET que as mostra (ronda em PC, V4 P4). A
# página era a resposta do POST: recarregar criava outro convite, e
# voltar ao endereço dava 405. Agora o POST redirecciona, e o GET tira a
# ligação daqui -- à segunda vez já não está, e nada se cria de novo.
# ponytail: em memória, por sessão; um painel reiniciado entre os dois
# pedidos perde-a (gera-se outra), e isso chega para um processo só.
_POR_MOSTRAR = {}
LIGACAO_UMA_VEZ = "/configuracoes/conta/ligacao"


def mostrar_uma_vez(titulo, frase, ligacao, rotulo, voltar):
    """Guarda a ligação para a sessão de quem a criou e redirecciona para
    a página que a mostra, uma vez (Post/Redirect/Get)."""
    if len(_POR_MOSTRAR) > 200:
        _POR_MOSTRAR.clear()
    _POR_MOSTRAR[g.get("sessao") or ""] = {
        "titulo": titulo, "frase": frase, "ligacao": ligacao,
        "rotulo": rotulo, "voltar": voltar}
    return redirect(LIGACAO_UMA_VEZ)


def caixa_de_copiar(ligacao, rotulo):
    """A ligação num campo só de leitura, com o botão «Copiar». Uma por
    página (os `id`). Serve o convite e o repor das Configurações e, desde
    30/09/2026, o pedido aceite, que a mostrava num `<code>` sem botão
    (UX-7-LEIS J8)."""
    return (
        "<div class='copiar-linha'><input class='mg-field__input' type='text' "
        "id='ligacao-uma-vez' readonly value='%s' aria-label='%s' "
        "onfocus='this.select()'>"
        "<button type='button' class='mg-btn mg-btn--primary' "
        "id='copiar-ligacao'>Copiar</button></div>"
        "<script>document.getElementById('copiar-ligacao').addEventListener("
        "'click',function(){var b=this,i=document.getElementById('ligacao-uma-vez');"
        "i.select();var feito=function(){b.textContent='Copiada';};"
        "if(navigator.clipboard)navigator.clipboard.writeText(i.value).then(feito,"
        "function(){document.execCommand('copy');feito();});"
        "else{document.execCommand('copy');feito();}});</script>"
        % (html.escape(ligacao, quote=True), html.escape(rotulo, quote=True)))


@app.route("/configuracoes/conta/ligacao")
def ligacao_uma_vez():
    """A ligação acabada de criar, com o botão «Copiar». Recarregar não
    cria outra: a segunda vez diz que já se mostrou."""
    l = _POR_MOSTRAR.pop(g.get("sessao") or "", None)
    if l and "ligacao" in l:
        # fica só o «voltar» (G61 da 3.ª ronda): ao recarregar, o Voltar
        # levava o dono à /plataforma e não à empresa de onde veio
        _POR_MOSTRAR[g.get("sessao") or ""] = {"voltar": l["voltar"]}
    if not l or "ligacao" not in l:
        corpo = ("<div class='mg-card conf-cx'><p>Esta ligação já se mostrou e "
                 "não se volta a ver. Se se perdeu, gere outra: a anterior "
                 "deixa de servir.</p><p style='margin-top:14px'><a href='%s'>"
                 "Voltar</a></p></div>"
                 % html.escape(l["voltar"] if l else "/plataforma" if sou_dono()
                               else "/configuracoes/conta", quote=True))
    else:
        corpo = (
            "<div class='mg-card conf-cx'>"
            "<div class='mg-field__label'>%s</div><p class='nota'>%s</p>%s"
            "<p style='margin-top:14px'><a href='%s'>Voltar</a></p></div>"
            % (html.escape(l["titulo"]), l["frase"],
               caixa_de_copiar(l["ligacao"], l["rotulo"]),
               html.escape(l["voltar"], quote=True)))
    if sou_dono():
        return envolver("configuracoes", "Plataforma", "",
                        "<div class='larg'>%s</div>" % corpo,
                        titulo_aba="Ligação · Plataforma")
    return pagina_config("conta", corpo)


@app.route("/plataforma/convites/<int:convite_id>/<gesto>", methods=["POST"])
def plataforma_gesto_no_convite(convite_id, gesto):
    """Anular ou gerar de novo um convite, de qualquer empresa -- tambem
    os que o admin dela criou."""
    if gesto not in ("anular", "renovar"):
        abort(404)
    with liga() as c:
        convite = contas._convite_por_id(c, convite_id)
        if not convite:
            abort(404)
        codigo = (contas.renovar_convite(c, convite_id) if gesto == "renovar"
                  else contas.anular_convite(c, convite_id) and "")
    empresa_id = convite["empresa_id"]
    registar_evento("", "convite", "%s o convite de %s para %s (empresa %d)"
                    % ("gerou de novo" if codigo else "anulou",
                       convite["papel"], convite["email"] or "sem endereço",
                       empresa_id), quem=quem_sou() or "")
    if codigo and empresa_id in empresas_existentes():
        return _mostrar_convite(_empresa_ou_404(empresa_id), codigo, convite["papel"],
                                convite["email"] or "")
    return _volta_a("/plataforma/empresa/%d#convites" % empresa_id, "Convite anulado.")


@app.route("/plataforma/empresa/<int:id_>/<gesto>", methods=["POST"])
def plataforma_suspender(id_, gesto):
    """Suspende ou reactiva a empresa: nada se apaga. A lista vive no
    config.json da plataforma (`empresas_suspensas`), e a porta le-a."""
    if gesto not in ("suspender", "reactivar"):
        abort(404)
    e = _empresa_ou_404(id_)
    antes = empresas_suspensas()
    depois = (antes | {id_}) if gesto == "suspender" else (antes - {id_})
    gravar_config_registado({"empresas_suspensas": sorted(depois)},
                            quem=quem_sou() or "")
    # As sessões abertas dela NÃO se apagam (G53 da 3.ª ronda): apagadas,
    # quem estava dentro caía no site público sem uma palavra. A porta
    # recusa-lhes tudo menos o sair a partir do pedido seguinte -- com a
    # página «Acesso suspenso», a mesma de quem tenta entrar --, e isso é
    # que é suspender. Ao reactivar, voltam onde estavam.
    with com_empresa(id_):
        registar("", "suporte", "empresa %s pelo dono da plataforma"
                 % ("suspensa" if gesto == "suspender" else "reactivada"))
    return _volta_a("/plataforma/empresa/%d" % id_, "%s %s."
                    % (e["nome"], "suspensa" if gesto == "suspender" else "reactivada"))


def _o_mesmo_nome(a, b):
    """O nome escrito para confirmar bate com o da empresa: sem contar
    espacos a mais nem maiusculas."""
    return " ".join((a or "").split()).casefold() == " ".join((b or "").split()).casefold()


def _cartao_de_apagar(e, n_contas, n_convites, tem_o_dono=False):
    """O cartao de perigo do fim da pagina da empresa (26/09/2026, pedido
    dele: «eu como dono não consigo apagar empresas»; so havia o
    `--apagar-empresa` da consola). Diz o que sai, com os numeros, e o
    que fica; confirma-se escrevendo o nome."""
    with com_empresa(e["id"]):
        with liga() as c:
            n = {t: c.execute("SELECT COUNT(*) FROM %s" % t).fetchone()[0]
                 for t in ("propostas", "tarefas", "contactos", "historico")}
    nome = html.escape(e["nome"], quote=True)
    corpo = (
        "<p>Sai da plataforma: %s, %s, %s, %s do histórico, a configuração, a "
        "triagem, %s%s e %s.</p>"
        "<p class='nota'>Fica guardado: uma cópia da base de antes e a pasta da "
        "empresa em <code>copias/</code>, de onde se recupera.</p>"
        "<form method='post' action='/plataforma/empresa/%d/apagar' "
        "class='mg-row' style='gap:12px;flex-wrap:wrap;align-items:flex-end;"
        "margin-top:16px'><div class='mg-field'>"
        "<label class='mg-field__label' for='apagar-nome'>Para confirmar, "
        "escreva o nome da empresa: <b>%s</b></label>"
        "<input class='mg-field__input' id='apagar-nome' name='nome' type='text' "
        "required autocomplete='off' spellcheck='false'></div>"
        "<button type='submit' class='mg-btn mg-btn--danger'>Apagar a empresa"
        "</button></form>"
        % (plural(n["propostas"], "proposta"), plural(n["tarefas"], "tarefa"),
           plural(n["contactos"], "contacto"), plural(n["historico"], "linha"),
           plural(n_contas, "conta"),
           " (a do dono fica, sem empresa)" if tem_o_dono else "",
           plural(n_convites, "convite por usar",
                                             "convites por usar"),
           e["id"], nome))
    return cartao("Apagar a empresa", corpo, id_="apagar")


@app.route("/plataforma/empresa/<int:id_>/apagar", methods=["POST"])
def plataforma_apagar_empresa(id_):
    """Apaga a empresa pelo painel: o `apagar_empresa()` da consola, com o
    nome escrito como confirmacao. So o dono (o prefixo `/plataforma` esta
    em ROTAS_SO_DONO), com o CSRF da porta, e nunca no modo de suporte (a
    porta recusa todos os POST fora do PODE_A_VER_COMO).

    Sincrono: a copia de antes e so as linhas da empresa no radar.db
    (4/10/2026; era a base inteira, ~1 minuto)."""
    e = _empresa_ou_404(id_)
    if not _o_mesmo_nome(request.form.get("nome"), e["nome"]):
        return _volta_a("/plataforma/empresa/%d#apagar" % id_,
                        "O nome escrito não é o da empresa: nada se apagou.", erro=True)
    try:
        copia, guardada, _ = apagar_empresa(id_)
    except (ValueError, OSError, sqlite3.Error) as erro:
        return _volta_a("/plataforma/empresa/%d#apagar" % id_,
                        "Não se apagou: %s" % erro, erro=True)
    registar_evento("", "empresa", "apagou a empresa %d (%s); cópia em %s, "
                    "pasta em %s" % (id_, e["nome"], copia, guardada),
                    quem=quem_sou() or "o dono")
    return _volta_a("/plataforma", "%s saiu da plataforma. A pasta da empresa, com "
                    "as contas e o plano em plataforma.json, está em copias/%s."
                    % (e["nome"], os.path.basename(guardada)))


@app.route("/plataforma/empresa/<int:id_>/ver-como", methods=["POST"])
def plataforma_ver_como(id_):
    """Entra no modo de suporte: a aplicacao da empresa, como ela a ve, e
    nada se grava -- a porta recusa todos os POST, e o `liga()` junta o
    ficheiro dela so de leitura. E da SESSAO (`sessoes.ver_como`); cada
    entrada fica no historico da empresa, que o admin dela ve na Conta,
    e nos eventos da plataforma."""
    e = _empresa_ou_404(id_)
    if not g.get("sessao"):
        return _volta_a("/plataforma/empresa/%d" % id_, "O modo de suporte precisa de "
                        "uma sessão: entre com a palavra-passe.", erro=True)
    with liga() as c:
        contas.marcar_ver_como(c, g.sessao, id_)
    quem = quem_sou() or "o dono"
    with com_empresa(id_):
        registar("", "suporte", "o dono da plataforma (%s) entrou para ver, só leitura"
                 % quem)
    registar_evento("", "suporte", "entrou para ver a empresa %d (%s), só leitura"
                    % (id_, e["nome"]), quem=quem)
    return redirect("/")


@app.route("/plataforma/ver-como/sair", methods=["POST"])
def plataforma_ver_como_sair():
    """Sai do modo de suporte e volta a pagina da empresa. A empresa deixa
    de ser a do pedido so de leitura antes de se escrever a saida no
    historico dela."""
    id_ = g.get("ver_como")
    with liga() as c:
        contas.marcar_ver_como(c, g.get("sessao"), None)
    if id_ is None:
        return redirect("/plataforma")
    g.ver_como = None
    quem = quem_sou() or "o dono"
    with com_empresa(id_):
        registar("", "suporte", "o dono da plataforma (%s) saiu" % quem)
    registar_evento("", "suporte", "saiu da empresa %d" % id_, quem=quem)
    return redirect("/plataforma/empresa/%d" % id_)

def volta_config(seccao, aviso, erro=False, **fica):
    """De volta à secção com o aviso; o `fica` é o que se escreveu e o
    formulário volta a mostrar (5.ª ronda: num erro da Conta o e-mail de
    contacto escrito perdia-se)."""
    pares = {"aviso": aviso}
    if erro:
        pares["tom"] = "erro"
    pares.update({k: v for k, v in fica.items() if v})
    return redirect("/configuracoes/%s?%s" % (seccao, urlencode(pares)))


def _campo(rotulo, nome, valor, tipo="text", nota="", extra=""):
    return ("<label class='conf-campo'><span>%s</span>"
            "<input type='%s' name='%s' value='%s'%s>%s</label>"
            % (html.escape(rotulo), tipo, nome, html.escape(str(valor), quote=True),
               (" " + extra) if extra else "",
               ("<small>%s</small>" % nota) if nota else ""))


def _interruptor(rotulo, nome, ligado, nota=""):
    return ("<label class='conf-campo conf-check'><input type='checkbox' "
            "name='%s' value='1'%s><span>%s</span>%s</label>"
            % (nome, " checked" if ligado else "", html.escape(rotulo),
               ("<small>%s</small>" % nota) if nota else ""))


def _inteiro(form, nome, minimo, maximo, rotulo):
    """Um inteiro do formulario dentro de limites, ou ValueError com a
    frase para o ecra. Uma janela de detalhe de 0 dias cala a recolha
    em silencio -- e por isso que ha limites e nao so int()."""
    bruto = (form.get(nome) or "").strip()
    # só algarismos: o int() aceita «1_000» e os dígitos de outras escritas
    if not re.fullmatch(r"-?[0-9]+", bruto):
        raise ValueError("«%s» não é um número (%s)." % (corta(bruto, 20), rotulo))
    n = int(bruto)
    if not minimo <= n <= maximo:
        raise ValueError("%s vai de %d a %d." % (rotulo, minimo, maximo))
    return n


def volta_config_erro(seccao, aviso):
    return volta_config(seccao, aviso, erro=True)


