@app.route("/alertas/remetente", methods=["POST"])
def alertas_remetente():
    """Quem envia o resumo: conta, servidor, porta para o config.json;
    a palavra-passe para o email_senha.txt, e so se vier preenchida."""
    de = (request.form.get("de") or "").strip()
    servidor = (request.form.get("servidor") or "").strip()
    if de and not RX_EMAIL.fullmatch(de):
        return volta_config_erro("alertas", "«%s» não é um e-mail. Nada foi "
                                 "guardado." % corta(de, 60))
    try:
        porta = _inteiro(request.form, "porta", 1, 65535, "a porta")
    except ValueError as erro:
        return volta_config_erro("alertas", str(erro))
    gravar_config_registado({"email": {"de": de, "servidor": servidor,
                                       "porta": porta}})
    senha = request.form.get("senha") or ""
    if senha.strip() and not (os.environ.get("RADAR_EMAIL_SENHA") or "").strip():
        with open(os.path.join(BASE_DIR, "email_senha.txt"), "w",
                  encoding="utf-8") as f:
            f.write(senha.strip() + "\n")
        so_o_dono(os.path.join(BASE_DIR, "email_senha.txt"))
        registar("", "configuração", "email_senha.txt: palavra-passe nova")
    return volta_config("alertas", "Conta que envia guardada.")


@app.route("/configuracoes/recolha", methods=["GET", "POST"])
def config_recolha():
    cfg = ler_config()
    if request.method == "POST":
        try:
            horas = []
            for h in (request.form.get("horas") or "").replace(";", ",").split(","):
                h = h.strip()
                if not h:
                    continue
                if not re.fullmatch(r"([01]\d|2[0-3]):[0-5]\d", h):
                    raise ValueError("«%s» não é uma hora HH:MM." % h)
                horas.append(h)
            if not horas:
                raise ValueError("É precisa pelo menos uma hora de verificação.")
            mudancas = {
                "horas_verificacao": sorted(set(horas)),
                "dias_catchup": _inteiro(request.form, "dias_catchup", 0, 90,
                                         "a janela de recuperação"),
                "detalhe_dias": _inteiro(request.form, "detalhe_dias", 1, 3650,
                                         "a janela do detalhe"),
                "detalhes_por_volta": _inteiro(request.form, "detalhes_por_volta",
                                               1, 500, "detalhes por volta"),
                "relidos_por_volta": _inteiro(request.form, "relidos_por_volta",
                                              0, 200, "relidos por volta"),
                "vortal_preliminares": bool(request.form.get("vortal_preliminares")),
                "recuperar_slot_falhado": bool(request.form.get("recuperar_slot_falhado")),
            }
        except ValueError as erro:
            return volta_config_erro("recolha", str(erro))
        gravar_config_registado(mudancas)
        return volta_config("recolha", "Recolha guardada. As horas novas "
                            "valem já, no painel e no temporizador do "
                            "sistema.")
    faltam = tarefas_em_falta()
    corpo = (
        "<form method='post' action='/configuracoes/recolha' class='conf-form'>"
        + _campo("Horas da verificação", "horas",
                 ", ".join(cfg.get("horas_verificacao") or []),
                 nota="HH:MM, separadas por vírgula. O temporizador do sistema "
                      "dispara de hora a hora, e só verifica nas horas desta lista.")
        + _campo("Janela de recuperação (dias)", "dias_catchup", cfg.get("dias_catchup", 15), extra="inputmode='numeric'",
                 nota="quantos dias para trás o radar volta a olhar quando falha um slot")
        + _campo("Janela do detalhe (dias)", "detalhe_dias", cfg.get("detalhe_dias", 60), extra="inputmode='numeric'",
                 nota="a rotina só lê o detalhe (CPV, prazo, preço) dos anúncios destes últimos dias")
        + _campo("Detalhes por volta", "detalhes_por_volta", cfg.get("detalhes_por_volta", 40),
                 extra="inputmode='numeric'")
        + _campo("Relidos por volta", "relidos_por_volta", cfg.get("relidos_por_volta", 25), extra="inputmode='numeric'",
                 nota="anúncios com interesse ou proposta em curso, de prazo aberto, que se releem para apanhar alterações")
        + _interruptor("Trazer as consultas preliminares da Vortal", "vortal_preliminares",
                       cfg.get("vortal_preliminares", True))
        + _interruptor("Recuperar um slot falhado na verificação seguinte",
                       "recuperar_slot_falhado", cfg.get("recuperar_slot_falhado", True))
        + "<button type='submit' class='mg-btn mg-btn--primary'>Guardar</button></form>"
        + ("<div class='mg-alert mg-alert--danger' style='margin-top:16px'>As tarefas agendadas "
           "estão por criar (%s): corra o agendar.sh.</div>"
           % html.escape(", ".join(faltam)) if faltam else
           "<div class='nota' style='margin-top:16px'>As tarefas agendadas do "
           "sistema estão criadas.</div>"))
    return pagina_config("recolha", "<div class='mg-card conf-cx'>" + corpo + "</div>")


def _estado_da_chave(nomes, variavel):
    """(texto, esta_bem, por_variavel) para o ecra das chaves."""
    if (os.environ.get(variavel) or "").strip():
        return "definida pela variável %s" % variavel, True, True
    for nome in nomes:
        caminho = os.path.join(BASE_DIR, nome)
        if os.path.exists(caminho):
            try:
                with open(caminho, encoding="utf-8") as f:
                    if f.read().strip():
                        return ("no %s desde %s" % (
                            nome, datetime.fromtimestamp(
                                os.path.getmtime(caminho)).strftime("%d/%m/%Y")),
                            True, False)
            except OSError:
                pass
    return "falta", False, False


@app.route("/configuracoes/leitura", methods=["GET", "POST"])
def config_leitura():
    cfg = ler_config()
    nomes_forn = [f[0] for f in FORNECEDORES]
    if request.method == "POST":
        forn = (request.form.get("fornecedor_pecas") or "").strip()
        if forn and forn not in nomes_forn:
            return volta_config_erro("leitura", "Fornecedor desconhecido: %s" % forn)
        modelos = dict(cfg.get("modelos_pecas") or {})
        for nome in nomes_forn:
            modelos[nome] = (request.form.get("modelo_" + nome) or "").strip()
        gravar_config_registado({"fornecedor_pecas": forn, "modelos_pecas": modelos})
        # as chaves: so as que vieram preenchidas, e nunca por cima de
        # uma variavel de ambiente
        escritas = []
        for nome, _, _, ficheiros, variavel, _ in FORNECEDORES:
            nova = (request.form.get("chave_" + nome) or "").strip()
            if nova and not (os.environ.get(variavel) or "").strip():
                with open(os.path.join(BASE_DIR, ficheiros[-1] if nome != "groq"
                                       else "groq_API_KEY.txt"), "w",
                          encoding="utf-8") as f:
                    f.write(nova + "\n")
                so_o_dono(f.name)
                escritas.append(nome)
                registar("", "configuração", "chave de %s: nova" % nome)
        return volta_config("leitura", "Leitura das peças guardada%s."
                            % (" e chave%s de %s gravada%s"
                               % ("s" if len(escritas) > 1 else "",
                                  ", ".join(escritas),
                                  "s" if len(escritas) > 1 else "")
                               if escritas else ""))
    opcoes = "".join(
        "<option value='%s'%s>%s</option>"
        % (v, " selected" if v == (cfg.get("fornecedor_pecas") or "") else "", t)
        for v, t in [("", "a cadeia, por ordem (%s)" % " → ".join(nomes_forn))]
        + [(n, n) for n in nomes_forn])
    linhas = []
    for nome, _, omissao, ficheiros, variavel, _ in FORNECEDORES:
        texto, bem, por_var = _estado_da_chave(ficheiros, variavel)
        linhas.append(
            "<div class='conf-forn'><div class='mg-field__label'>%s</div>"
            "<div class='saude'>%s</div>%s%s</div>"
            % (html.escape(nome),
               linhas_de_saude([("Chave", html.escape(texto), bem)], "var(--warning)"),
               _campo("Modelo", "modelo_" + nome,
                      modelo_do_fornecedor(cfg, nome, omissao),
                      nota="de origem: %s" % html.escape(omissao)),
               "" if por_var else
               _campo("Chave nova", "chave_" + nome, "", tipo="password",
                      # sem o nome do ficheiro (E58, ronda em PC): a quem
                      # usa, «groq_API_KEY.txt» não dizia nada de útil
                      nota="só se grava se escrever uma; fica num ficheiro "
                           "deste computador, nunca na base nem no git",
                      extra="autocomplete='new-password'")))
    corpo = (
        "<form method='post' action='/configuracoes/leitura' class='conf-form'>"
        "<label class='conf-campo'><span>Fornecedor em uso</span>"
        "<select name='fornecedor_pecas'>%s</select>"
        "<small>Cada pedido desce a cadeia até alguém responder; escolher "
        "um fixa-o como primeiro.</small></label>%s"
        "<button type='submit' class='mg-btn mg-btn--primary'>Guardar</button></form>"
        % (opcoes, "".join(linhas)))
    return pagina_config("leitura", "<div class='mg-card conf-cx'>" + corpo + "</div>")


def _estado_da_captura(nome_base):
    caminho = os.path.join(BASE_DIR, nome_base + ".txt")
    if not os.path.exists(caminho):
        return "em falta", False
    texto = carregar_curl(nome_base)
    try:
        pedido = parse_curl(texto) if texto else None
    except ValueError:
        pedido = None
    if not pedido or not pedido.get("headers"):
        return "ilegível — refaz a captura", False
    idade = datetime.fromtimestamp(os.path.getmtime(caminho))
    return ("válida, de %s (%d cabeçalhos)"
            % (idade.strftime("%d/%m/%Y"), len(pedido["headers"])), True)


@app.route("/configuracoes/capturas", methods=["GET", "POST"])
def config_capturas():
    if request.method == "POST":
        qual = (request.form.get("qual") or "").strip()
        if qual not in ("curl_DR", "curl_detalhe"):
            return volta_config_erro("capturas", "Captura desconhecida.")
        texto = (request.form.get("texto") or "").strip()
        # valida-se ANTES de tocar no ficheiro: uma colagem a meio nao
        # pode deixar a recolha sem captura nenhuma
        try:
            pedido = parse_curl(texto) if texto else None
        except ValueError as erro:
            pedido = None
            porque = str(erro)
        else:
            porque = "não parece um «Copy as cURL»"
        if not pedido or not pedido.get("headers"):
            return volta_config_erro("capturas", "Não gravei: %s." % porque)
        if qual == "curl_DR" and not pedido.get("body"):
            return volta_config_erro("capturas", "Não gravei: a captura da pesquisa "
                                "tem de trazer o corpo do pedido (--data-raw).")
        with open(os.path.join(BASE_DIR, qual + ".txt"), "w", encoding="utf-8") as f:
            f.write(texto + "\n")
        so_o_dono(os.path.join(BASE_DIR, qual + ".txt"))
        registar("", "configuração", "%s.txt: captura nova (%d cabeçalhos)"
                 % (qual, len(pedido["headers"])))
        return volta_config("capturas", "Captura %s.txt gravada." % qual)
    blocos = []
    for nome_base, titulo, nota in (
            ("curl_DR", "curl_DR.txt — a pesquisa",
             "o pedido da lista de anúncios; leva o corpo (--data-raw)"),
            ("curl_detalhe", "curl_detalhe.txt — o detalhe",
             "o pedido da página de um anúncio")):
        texto, bem = _estado_da_captura(nome_base)
        blocos.append(
            "<div class='conf-forn'><div class='mg-field__label'>%s</div>"
            "<div class='nota' style='margin:6px 0 10px'>%s. Como se faz a "
            "captura está no LEIA-ME, secção 3.</div>"
            "<div class='saude'>%s</div>"
            "<form method='post' action='/configuracoes/capturas' class='conf-form'>"
            "<input type='hidden' name='qual' value='%s'>"
            "<textarea name='texto' rows='5' placeholder='cola aqui o Copy as cURL'></textarea>"
            "<button type='submit' class='mg-btn mg-btn--primary'>Gravar esta captura</button>"
            "</form></div>"
            % (html.escape(titulo), html.escape(nota),
               linhas_de_saude([("Estado", html.escape(texto), bem)]),
               nome_base))
    return pagina_config("capturas", "<div class='mg-card conf-cx'>" + "".join(blocos) + "</div>")


@app.route("/configuracoes/copias", methods=["GET", "POST"])
def config_copias():
    cfg = ler_config()
    if request.method == "POST":
        try:
            mudancas = {
                "copia_de_seguranca": bool(request.form.get("copia_de_seguranca")),
                "copias_a_guardar": _inteiro(request.form, "copias_a_guardar", 1, 60,
                                             "cópias a guardar"),
            }
        except ValueError as erro:
            return volta_config_erro("copias", str(erro))
        gravar_config_registado(mudancas)
        return volta_config("copias", "Cópias guardadas.")
    existentes = []
    if os.path.isdir(COPIAS):
        for nome in sorted(os.listdir(COPIAS), reverse=True):
            caminho = os.path.join(COPIAS, nome)
            if nome.endswith(".db") and os.path.isfile(caminho):
                # pelo formatador único: a cópia de uma empresa pequena
                # dizia «0 MB» (E46), e uma cópia de 0 MB lê-se vazia
                existentes.append(
                    "<div class='l'><span class='t'>%s</span><span class='v'>%s</span></div>"
                    % (html.escape(nome), tamanho_legivel(os.path.getsize(caminho))))
    ultima = le_marca("ultima_copia", "ainda nenhuma")
    corpo = (
        "<form method='post' action='/configuracoes/copias' class='conf-form'>"
        + _interruptor("Cópia diária das bases", "copia_de_seguranca",
                       cfg.get("copia_de_seguranca", True),
                       nota="a plataforma e o ficheiro de cada empresa; o trabalho das empresas não se recupera de mais lado nenhum")
        + _campo("Cópias a guardar", "copias_a_guardar", cfg.get("copias_a_guardar", 7), extra="inputmode='numeric'",
                 nota="uma por dia; as mais velhas apagam-se. A base tem 1,3 GB — conta com isso")
        + "<button type='submit' class='mg-btn mg-btn--primary'>Guardar</button></form>"
        + "<div class='mg-field__label' style='margin:22px 0 6px'>O que existe em copias/</div>"
        + "<div class='nota' style='margin-bottom:10px'>Última: %s</div>" % html.escape(ultima)
        + "<div class='nota' style='margin-bottom:10px'>Fora deste PC: %s "
          "<span style='color:var(--ink-muted)'>(o destino configura-se uma vez com o "
          "copias_fora.sh)</span></div>"
          % html.escape(le_marca("ultima_copia_fora", "ainda nenhuma"))
        + "<div class='nota' style='margin-bottom:10px'>Ensaio de restauro: %s%s</div>"
          % ("<br>".join(html.escape(x) for x in
                         le_marca("ultimo_ensaio_copia", "ainda nenhum").split(" · ")),
             " <span style='color:var(--ink-muted)'>(python radar.py "
             "--ensaiar-copia)</span>" if sou_dono() else "")
        + "<div class='saude'>%s</div>" % ("".join(existentes) or
                                           "<div class='nota'>nenhuma ainda</div>"))
    return pagina_config("copias", "<div class='mg-card conf-cx'>" + corpo + "</div>")


def pasta_das_importacoes():
    """A pasta das importacoes DA EMPRESA ACTIVA: `empresas/<id>/importacoes/`.

    Ate 26/09/2026 o .xlsx carregado ia para a `importacoes/` da raiz,
    que era de todas as empresas, e a confirmacao aceitava qualquer nome
    de la: o nome leva a data e a hora, e a empresa B confirmava na base
    dela o ficheiro que a A tinha acabado de carregar -- lia os
    concursos, os precos e as notas da A. A pasta antiga fica onde esta,
    e nenhuma rota a le."""
    return os.path.join(os.path.dirname(db_da_empresa()), empresa.PASTA_IMPORTACOES)


def _nome_de_importacao(nome):
    """So um nome de ficheiro dentro da pasta da empresa: nada de
    caminhos. Um nome com `/`, `\\` ou `..` recusa-se -- nao se
    «limpa» para o basename, que era aceitar um caminho e usar outro."""
    nome = (nome or "").strip()
    return nome if re.fullmatch(r"\w[\w\-]*(\.[\w\-]+)*\.xlsx", nome) else ""


def _base_no_ensaio(linhas, cfg=None):
    """O que o Portal BASE diz de cada linha decidida (E49 da segunda
    ronda, 26/09/2026): um «Ganho» importado que o BASE dá a outro
    entrava sem aviso -- e para as propostas abertas a ficha já fazia
    este cruzamento. Só avisa: quem sabe se fomos nós é a empresa."""
    cfg = ler_config() if cfg is None else cfg
    for l in linhas:
        estado = simplifica(l.get("status") or "")
        if not (l.get("ok") and l.get("ref") and estado in ("ganho", "perdido")):
            continue
        desfecho = desfecho_do_anuncio(l["ref"])
        if not desfecho:
            continue
        quem = corta(" · ".join(sorted({n for d in desfecho
                                        for n in (d["ganhou"] or "").split("|")
                                        if n})), 80) or "?"
        nos = fomos_nos(desfecho, cfg)
        if estado == "ganho" and nos is False:
            l["base"] = "não bate: o Portal BASE dá-o a %s" % quem
        elif estado == "perdido" and nos is True:
            l["base"] = "não bate: o Portal BASE dá-o a nós"
        else:
            l["base"] = "adjudicado a %s" % quem


def _tabela_do_ensaio(linhas):
    corpo = []
    for l in linhas:
        problemas = "".join("<div class='mau'>%s</div>" % html.escape(pr) for pr in l["problemas"])
        avisos = "".join("<div class='aviso'>%s</div>" % html.escape(av) for av in l.get("avisos", []))
        # Um veredicto só, antes dos avisos (segunda ronda, 26/09/2026:
        # um erro a vermelho e um aviso a âmbar na mesma linha não diziam
        # se ela entrava); e o que faz ao que já existe.
        veredicto = ("<b class='ok'>entra</b>" if l["ok"]
                     else "<b class='mau'>não entra</b>")
        efeito = ("<div>%s</div>" % html.escape(l["efeito"])) if l.get("efeito") else ""
        base = l.get("base", "")
        corpo.append(
            "<tr class='%s'><td class='d'>%d</td><td class='n'>%s</td><td class='o'>%s</td>"
            "<td class='d'>%s</td><td>%s</td><td class='p'>%s</td><td class='d'>%s</td>"
            "<td>%s</td><td>%s</td></tr>"
            % ("ok" if l["ok"] else "erro", l["linha"],
               # o que se escreveu, quando não se leu: «—» não deixava ver
               # o que corrigir
               html.escape(l["ref"] or l.get("ref_escrita") or "—"),
               html.escape(corta(l["titulo"] or "", 90)),
               "L%d" % l["lote"] if l["lote"] is not None else "—",
               html.escape(l["status"] or "—"),
               html.escape(preco_pt(_texto_do_preco(l["valor_proposta"]))) if l["valor_proposta"] else "—",
               # a data da decisão à vista (E16, ronda em PC): lia-se e
               # gravava-se, e o ensaio não a mostrava
               data_pt(l.get("data_decisao") or "", "—"),
               ("<span class='%s'>%s</span>" % ("mau" if base.startswith("não bate")
                                                 else "", html.escape(base)))
               if base else "—",
               veredicto + efeito + problemas + avisos))
    return ("<div class='mercado-tab'><table class='mg-table tab-mercado tab-ensaio'><thead><tr>"
            "<th>Linha</th><th>Referência</th><th>Anúncio</th><th>Lote</th><th>Estado</th>"
            "<th class='p'>Proposta</th><th>Decisão</th><th>BASE diz</th><th>Ensaio</th>"
            "</tr></thead>"
            "<tbody>%s</tbody></table></div>"
            % "".join(corpo))


@app.route("/configuracoes/importar", methods=["GET", "POST"])
def config_importar():
    """O registo da empresa entra por aqui: descarregar o modelo, carregar o
    ficheiro preenchido, ver o ensaio, confirmar. Decisao do Afonso a
    8/09/2026 -- o Excel antigo deixou de contar para a aplicacao."""
    if request.method == "POST":
        ficheiro = request.files.get("ficheiro")
        if not ficheiro or not ficheiro.filename:
            return volta_config_erro("importar", "Escolha o ficheiro .xlsx preenchido.")
        if not ficheiro.filename.lower().endswith(".xlsx"):
            return volta_config_erro("importar", "Só .xlsx: é o formato do modelo.")
        pasta = pasta_das_importacoes()
        os.makedirs(pasta, exist_ok=True)
        # a data para se ler, e 16 caracteres ao acaso para o nome nao se
        # adivinhar; o do utilizador sem pontos seguidos (`..`)
        nome = "%s-%s-%s" % (datetime.now().strftime("%Y%m%d-%H%M%S"),
                             os.urandom(8).hex(),
                             re.sub(r"\.{2,}", ".", re.sub(r"[^\w.\-]+", "_",
                                    os.path.basename(ficheiro.filename)))[-60:])
        if not nome.endswith(".xlsx"):
            nome += ".xlsx"
        caminho = os.path.join(pasta, nome)
        ficheiro.save(caminho)
        try:
            linhas = empresa.ler_modelo(caminho)
        except Exception as erro:            # openpyxl levanta de tudo num ficheiro estragado
            os.remove(caminho)
            return volta_config_erro("importar", "Não consegui ler o ficheiro: %s" % str(erro)[:120])
        with liga() as c:
            linhas, contagens = empresa.ensaio_modelo(c, linhas)
        if not linhas:
            os.remove(caminho)
            return volta_config_erro("importar", "O ficheiro não tem linhas preenchidas na folha «Registo».")
        _base_no_ensaio(linhas)
        ignoradas = empresa.colunas_ignoradas(caminho)
        confirmar = (
            "<form method='post' action='/configuracoes/importar/confirmar' class='conf-form' "
            "style='margin-top:16px'><input type='hidden' name='ficheiro' value='%s'>"
            "<button type='submit' class='mg-btn mg-btn--primary'%s>Gravar %d proposta%s</button>"
            "<small>As linhas com erro ficam de fora. Uma referência que já entrou por "
            "outra importação fica com o que esta traz. Depois de gravar, a importação "
            "desfaz-se aqui, enquanto ninguém mexer nas propostas que ela tocou.</small></form>"
            % (html.escape(nome, quote=True), "" if contagens["ok"] else " disabled",
               contagens["ok"], "" if contagens["ok"] == 1 else "s"))
        # O que muda no que já existe diz-se em cima (E17): «quase apaguei
        # um Ganho de 362 mil euros de um colega e o ensaio disse-me que
        # estava tudo bem».
        topo = "".join(
            "<div class='mg-alert mg-alert--warning'>%s</div>" % html.escape(frase)
            for frase in (
                ["%d linha%s vai alterar proposta%s que já existe%s — veja a coluna "
                 "Ensaio." % (contagens["alteram"], "" if contagens["alteram"] == 1 else "s",
                              "" if contagens["alteram"] == 1 else "s",
                              "" if contagens["alteram"] == 1 else "m")]
                if contagens["alteram"] else []) + (
                ["%d linha%s não muda%s a proposta, que já está noutra fase."
                 % (contagens["mantem"], "" if contagens["mantem"] == 1 else "s",
                    "" if contagens["mantem"] == 1 else "m")]
                if contagens["mantem"] else []) + [
                "A coluna %s «%s» não é do modelo e é ignorada." % (letra, titulo)
                for letra, titulo in ignoradas])
        corpo = (
            "<div class='mg-field__label'>Ensaio de %s</div>"
            "<div class='nota' style='margin:6px 0 12px'>%d linha%s lida%s: <b>%d entra%s</b> "
            "em %d anúncio%s, <b>%d com erro</b>. Nada foi gravado ainda.</div>%s%s%s"
            % (html.escape(ficheiro.filename), contagens["total"],
               "" if contagens["total"] == 1 else "s", "" if contagens["total"] == 1 else "s",
               contagens["ok"], "" if contagens["ok"] == 1 else "m",
               contagens["anuncios"], "" if contagens["anuncios"] == 1 else "s",
               contagens["com_erro"], topo, _tabela_do_ensaio(linhas), confirmar))
        return pagina_config("importar", "<div class='mg-card conf-cx'>" + corpo + "</div>")
    with liga() as c:
        n_modelo = c.execute("SELECT COUNT(*), COUNT(DISTINCT ref) FROM empresa "
                             "WHERE folha='modelo'").fetchone()
        ultima = c.execute("SELECT MAX(importado_em) FROM empresa WHERE folha='modelo'").fetchone()[0]
    # A primeira etiqueta de um cartão com faixa esconde-se (a faixa já
    # diz o título), e o «1. O modelo» sumia-se: ficava o «2.» sozinho
    # (E58). A frase de abertura vem antes, e os dois passos vêem-se.
    corpo = (
        "<div class='nota' style='margin-bottom:14px'>Dois passos: descarregar "
        "o modelo e preenchê-lo, e depois carregar o ficheiro preenchido.</div>"
        "<div class='mg-field__label'>1. O modelo</div>"
        "<div class='nota' style='margin:6px 0 12px'>Um Excel vazio com as colunas que o Mira Gov "
        "precisa e listas de escolha no estado e na razão. Uma linha por concurso, ou por lote "
        "quando o concurso tem lotes. A chave é a referência do anúncio no DR (ex. "
        "<code>1947/2026</code>), tal como a ficha a mostra.</div>"
        "<a class='mg-btn mg-btn--secondary' href='/configuracoes/importar/modelo.xlsx'>Descarregar o modelo</a>"
        "<div class='mg-field__label' style='margin:26px 0 6px'>2. O ficheiro preenchido</div>"
        "<div class='nota' style='margin-bottom:12px'>Primeiro vê-se um ensaio: o que liga a que "
        "anúncio, o que não liga e porquê. Só se grava depois de confirmar.</div>"
        "<form method='post' action='/configuracoes/importar' enctype='multipart/form-data' "
        "class='conf-form'><label class='conf-campo'><span>Ficheiro .xlsx</span>"
        "<input type='file' name='ficheiro' accept='.xlsx' required></label>"
        "<button type='submit' class='mg-btn mg-btn--primary'>Ver o ensaio</button></form>"
        "<div class='mg-field__label' style='margin:26px 0 6px'>O que já está</div>"
        "<div class='nota'>%s</div>%s"
        % ("%s linha%s do modelo, em %s anúncio%s; última importação a %s."
           % (mil_pt(n_modelo[0]), "" if n_modelo[0] == 1 else "s", mil_pt(n_modelo[1]),
              "" if n_modelo[1] == 1 else "s", html.escape(data_hora_pt(ultima)))
           if n_modelo[0] else "Ainda não entrou nenhuma linha pelo modelo.",
           _lista_das_importacoes()))
    return pagina_config("importar", "<div class='mg-card conf-cx'>" + corpo + "</div>")


# --- desfazer uma importação (E18 da segunda ronda, 26/09/2026)
#
# «Enganei-me numa coluna e agora tenho quatro concursos de 2024 no "Por
# analisar" e não os consigo tirar de lá.» O `--empresa-desfazer` já o
# fazia pela consola, a partir de uma cópia; quem importa não tem
# consola. Cada importação guarda o ANTES e o DEPOIS das propostas e do
# registo que tocou, num ficheiro da pasta da empresa (e não da pasta
# `importacoes/`, que é de todas). Desfazer repõe o antes -- mas só onde
# a proposta ainda está como a importação a deixou: o que alguém mexeu
# depois é trabalho, e não se deita fora.

def _fotografia_da_importacao(c, refs):
    """{ref: {"propostas": [...], "registo": [...]}}, as linhas inteiras."""
    foto = {}
    for ref in refs:
        foto[ref] = {
            "propostas": [dict(r) for r in c.execute(
                "SELECT %s FROM propostas WHERE ref=? ORDER BY id"
                % ", ".join(COLUNAS_DA_PROPOSTA), (ref,))],
            "registo": [dict(r) for r in c.execute(
                "SELECT * FROM empresa WHERE ref=? AND folha='modelo' ORDER BY id",
                (ref,))]}
    return foto


def _guardar_desfazer(nome, antes, depois, hist):
    pasta = pasta_das_importacoes()
    os.makedirs(pasta, exist_ok=True)
    with open(os.path.join(pasta, nome + ".json"), "w", encoding="utf-8") as f:
        json.dump({"ficheiro": nome, "quem": quem_sou(),
                   "quando": datetime.now().strftime("%Y-%m-%d %H:%M"),
                   "antes": antes, "depois": depois, "historico": hist,
                   "desfeita_em": None}, f, ensure_ascii=False)
    so_o_dono(os.path.join(pasta, nome + ".json"))


def _importacoes_guardadas(limite=5):
    pasta = pasta_das_importacoes()
    if not os.path.isdir(pasta):
        return []
    fora = []
    # os .xlsx carregados vivem na mesma pasta desde 26/09/2026
    for nome in sorted((n for n in os.listdir(pasta) if n.endswith(".json")),
                       reverse=True)[:limite]:
        try:
            with open(os.path.join(pasta, nome), encoding="utf-8") as f:
                fora.append(json.load(f))
        except (OSError, ValueError):
            continue
    return fora


def _lista_das_importacoes():
    linhas = []
    for imp in _importacoes_guardadas():
        refs = sorted(imp["depois"])
        ligacoes = ", ".join("<a href='/anuncio/%s'>%s</a>"
                             % (quote(r, safe=""), html.escape(r)) for r in refs[:12])
        if len(refs) > 12:
            ligacoes += " e mais %d" % (len(refs) - 12)
        linhas.append(
            "<div class='l'><span class='t'>%s, por %s: %d anúncio%s (%s)</span>"
            "<span class='v'>%s</span></div>"
            % (html.escape(data_hora_pt(imp["quando"])), html.escape(imp["quem"] or "—"),
               len(refs), "" if len(refs) == 1 else "s", ligacoes or "nenhum",
               ("desfeita a %s" % html.escape(data_hora_pt(imp["desfeita_em"])))
               if imp.get("desfeita_em") else
               accao("/configuracoes/importar/desfazer", "desfazer", "mini",
                     "Desfazer esta importação? As propostas que ela tocou voltam "
                     "a como estavam antes dela.",
                     campos={"ficheiro": imp["ficheiro"]})))
    return ("<div class='saude' style='margin-top:10px'>%s</div>" % "".join(linhas)
            if linhas else "")


def desfazer_importacao(nome):
    """Repõe o antes de uma importação. Devolve (repostas, deixadas), ou
    None se não há registo dela. Um anúncio cujas propostas já não estão
    como a importação as deixou fica como está: alguém trabalhou nele."""
    caminho = os.path.join(pasta_das_importacoes(), nome + ".json")
    if not os.path.exists(caminho):
        return None
    with open(caminho, encoding="utf-8") as f:
        imp = json.load(f)
    if imp.get("desfeita_em"):
        return 0, []
    repostas, deixadas = 0, []
    with liga() as c:
        for ref, depois in imp["depois"].items():
            agora = _fotografia_da_importacao(c, [ref])[ref]
            if agora["propostas"] != depois["propostas"]:
                deixadas.append(ref)
                continue
            antes = imp["antes"].get(ref, {"propostas": [], "registo": []})
            # As que a importação criou saem com as tarefas delas; as que
            # já existiam voltam à linha de antes, e as tarefas ficam.
            ids_antes = {v["id"] for v in antes["propostas"]}
            for v in depois["propostas"]:
                if v["id"] not in ids_antes:
                    apagar_propostas(c, "id=?", (v["id"],))
            for v in antes["propostas"]:
                c.execute("DELETE FROM propostas WHERE id=?", (v["id"],))
                c.execute("INSERT INTO propostas (%s) VALUES (%s)"
                          % (", ".join(v), ", ".join("?" * len(v))), list(v.values()))
            c.execute("DELETE FROM empresa WHERE ref=? AND folha='modelo'", (ref,))
            for v in antes["registo"]:
                c.execute("INSERT INTO empresa (%s) VALUES (%s)"
                          % (", ".join(v), ", ".join("?" * len(v))), list(v.values()))
            if imp["historico"]:
                c.execute("DELETE FROM historico WHERE ref=? AND id IN (%s)"
                          % ",".join("?" * len(imp["historico"])),
                          [ref] + imp["historico"])
            repostas += 1
    imp["desfeita_em"] = datetime.now().strftime("%Y-%m-%d %H:%M")
    with open(caminho, "w", encoding="utf-8") as f:
        json.dump(imp, f, ensure_ascii=False)
    for ref in imp["depois"]:
        if ref not in deixadas:
            sincronizar_tarefas(ref)
    return repostas, deixadas


@app.route("/configuracoes/importar/desfazer", methods=["POST"])
def config_importar_desfazer():
    nome = _nome_de_importacao(request.form.get("ficheiro"))
    feito = desfazer_importacao(nome) if nome else None
    if feito is None:
        return volta_config_erro("importar", "Não encontro essa importação.")
    repostas, deixadas = feito
    registar("", "importação", "desfeita: %d anúncio%s reposto%s (%s)"
             % (repostas, "" if repostas == 1 else "s", "" if repostas == 1 else "s",
                nome))
    frase = "Importação desfeita: %d anúncio%s reposto%s." % (
        repostas, "" if repostas == 1 else "s", "" if repostas == 1 else "s")
    if deixadas:
        frase += (" Fica%s como está%s %s, que alguém mexeu depois de importar."
                  % ("" if len(deixadas) == 1 else "m",
                     "" if len(deixadas) == 1 else "o",
                     ", ".join(deixadas[:10])))
    return volta_config("importar", frase, erro=bool(deixadas))


@app.route("/configuracoes/importar/modelo.xlsx")
def config_importar_modelo():
    pasta = pasta_das_importacoes()
    os.makedirs(pasta, exist_ok=True)
    caminho = os.path.join(pasta, "modelo-registo-da-empresa.xlsx")
    empresa.escrever_modelo(caminho)
    return send_file(caminho, as_attachment=True,
                     download_name="registo-da-empresa.xlsx",
                     mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")


@app.route("/configuracoes/importar/confirmar", methods=["POST"])
def config_importar_confirmar():
    nome = _nome_de_importacao(request.form.get("ficheiro"))
    caminho = os.path.join(pasta_das_importacoes(), nome) if nome else ""
    if not nome or not os.path.exists(caminho):
        return volta_config_erro("importar", "O ficheiro do ensaio já não está cá; carregue-o outra vez.")
    linhas = empresa.ler_modelo(caminho)
    with liga() as c:
        linhas, contagens = empresa.ensaio_modelo(c, linhas)
        refs = sorted({l["ref"] for l in linhas if l.get("ok")})
        antes = _fotografia_da_importacao(c, refs)
        hist_de = c.execute("SELECT COALESCE(MAX(id), 0) FROM historico").fetchone()[0]
        resultado = empresa.aplicar_modelo(c, linhas, quem=quem_sou() or "modelo")
        hist = [r[0] for r in c.execute(
            "SELECT id FROM historico WHERE id > ?", (hist_de,))]
        depois = _fotografia_da_importacao(c, refs)
    _guardar_desfazer(nome, antes, depois, hist)
    registar("", "importação", "%d linhas do modelo, %d anúncios, %d com triagem aplicada (%s)"
             % (resultado["gravadas"], resultado["anuncios"], resultado["aplicadas"], nome))
    return volta_config("importar", "Importado: %d linha%s em %d anúncio%s; %d com a triagem "
                        "aplicada, %d com erro ficaram de fora."
                        % (resultado["gravadas"], "" if resultado["gravadas"] == 1 else "s",
                           resultado["anuncios"], "" if resultado["anuncios"] == 1 else "s",
                           resultado["aplicadas"], contagens["com_erro"]))


@app.route("/configuracoes/conta", methods=["GET", "POST"])
def config_conta():
    utilizador = g.get("utilizador")
    if not utilizador:
        return pagina_config("conta", "<div class='mg-card conf-cx'><div class='nota'>"
                             "Ainda não há conta. Na pasta do radar: "
                             "<code>python radar.py --criar-utilizador NOME</code>."
                             "</div></div>")
    if request.method == "POST":
        # A palavra-passe e o e-mail de contacto (1/10/2026), os dois com
        # a actual: o "nome a mostrar" saiu a 13/09/2026 (o utilizador
        # chega), e o utilizador em si nao se muda. O contacto e para onde
        # vai o «esqueci-me» -- muda-lo sem a actual era dar a quem
        # apanhasse uma sessao aberta a palavra-passe da conta.
        actual = request.form.get("actual") or ""
        nova = request.form.get("nova") or ""
        outra = request.form.get("outra") or ""
        contacto = request.form.get("contacto")
        # o registar() fica FORA do `with`: la dentro a transaccao esta
        # aberta e a segunda ligacao ficava a espera dela (database is
        # locked -- apanhado pelo teste)
        with liga() as c:
            linha = c.execute("SELECT hash, contacto FROM utilizadores WHERE id=?",
                              (utilizador["id"],)).fetchone()
            if not actual:
                # vazia não é errada (4.ª ronda): a frase acusava um engano
                return volta_config("conta", erro=True, contacto=contacto or "", aviso="Para mudar isto, escreva a "
                                         "palavra-passe actual.")
            if not contas.verifica_senha(actual, linha["hash"]):
                return volta_config("conta", erro=True, contacto=contacto or "", aviso="A palavra-passe actual não está certa.")
            if nova != outra:
                return volta_config("conta", erro=True, contacto=contacto or "", aviso="As duas palavras-passe novas não são iguais.")
            muda_contacto = (contacto is not None
                             and contas.email_limpo(contacto) != linha["contacto"])
            # o contacto confere-se ANTES de a palavra-passe mudar: um
            # «não gravei» depois dela ficava com metade gravada
            porque = muda_contacto and contas.problema_do_contacto(
                c, utilizador["id"], contacto)
            if porque:
                return volta_config("conta", erro=True, contacto=contacto or "", aviso="Não gravei: %s." % porque)
            if not nova and not muda_contacto:
                # só a actual, nada para mudar (5.ª ronda: respondia «tem de
                # ter 8 caracteres» a uma nova que não se escreveu)
                return volta_config("conta", erro=True, contacto=contacto or "", aviso="Nada mudou: escreva a "
                                         "palavra-passe nova, ou um e-mail de "
                                         "contacto diferente.")
            muda_senha = bool(nova)
            if muda_senha:
                try:
                    contas.criar_utilizador(c, utilizador["email"], nova)
                except ValueError as erro:
                    return volta_config("conta", erro=True, contacto=contacto or "", aviso="Não gravei: %s." % erro)
                # e as outras sessões fecham-se, esta fica (6.ª ronda)
                contas.fechar_as_outras_sessoes(c, utilizador["id"],
                                                request.cookies.get("sessao"))
            if muda_contacto:
                contas.gravar_contacto(c, utilizador["id"], contacto)
        recado = {(True, False): "Palavra-passe mudada.",
                  (False, True): "E-mail de contacto mudado.",
                  (True, True): "Palavra-passe e e-mail de contacto mudados."}[
                      (muda_senha, muda_contacto)]
        registar("", "conta", recado.rstrip(".").lower())
        return volta_config("conta", recado)
    # O dono sem empresa (26/09/2026) tem conta como qualquer um -- a
    # palavra-passe, as sessoes, o aspecto --, mas nao tem empresa: os
    # blocos dela nao se desenham.
    da_empresa = sou_admin() and empresa_activa() != SEM_EMPRESA
    with liga() as c:
        sessoes = contas.sessoes_de(c, utilizador["id"])
        contacto = c.execute("SELECT contacto FROM utilizadores WHERE id=?",
                             (utilizador["id"],)).fetchone()["contacto"]
        # o que se escreveu antes de um erro volta ao campo
        contacto = request.args.get("contacto", contacto)
        todos = contas.utilizadores(c, empresa_activa()) if da_empresa else []
        convites = contas.convites_por_usar(c, empresa_activa()) if da_empresa else []
        suporte = [dict(r) for r in c.execute(
            "SELECT quem, detalhe, quando FROM historico WHERE accao='suporte' "
            "ORDER BY id DESC LIMIT 10")] if da_empresa else []
    # "iPhone até 10/10/2026 14:35", nao o User-Agent inteiro (13/09/2026);
    # e o ultimo uso e «terminar» em cada uma (G58 da 3.ª ronda)
    linhas = "".join(
        "<div class='l'><span class='ponto' style='background:%s'></span>"
        "<span class='t'>%s%s</span><span class='v'>usada %s &middot; até %s%s</span></div>"
        % ("var(--success)" if s_["token"] == g.get("sessao") else "var(--line-strong)",
           aparelho_do_agente(s_["agente"]),
           " (esta)" if s_["token"] == g.get("sessao") else "",
           html.escape(ha_quanto(s_["usada_em"])),
           html.escape(data_hora_pt(s_["expira"][:16])),
           "" if s_["token"] == g.get("sessao") else " &middot; " + accao(
               "/configuracoes/conta/sessoes/terminar", "terminar", "mini",
               campos={"n": s_["n"]},
               rotulo="Terminar a sessão de %s" % aparelho_do_agente(s_["agente"])))
        for s_ in sessoes) or "<div class='nota'>nenhuma sessão: a entrada é pelo acesso livre local</div>"
    if g.get("ver_como") is not None:
        # No «ver como» (G52 e G54 da 3.ª ronda): a palavra-passe, as
        # sessões, o aspecto e o segundo factor que aqui estavam eram os do
        # DONO, e o «Sair de todos» fechava-lhe as sessões com um 500. O
        # que fica é o que o gestor da empresa vê, e diz porquê.
        corpo = ("<div class='mg-alert mg-alert--info'>A palavra-passe, as "
                 "sessões e o aspecto são de cada pessoa: no modo de suporte "
                 "seriam os seus, e não os da empresa, e por isso não se "
                 "mostram. O resto é o que o gestor da empresa vê.</div>")
        if da_empresa:
            return pagina_config("conta", corpo + _cartoes_da_empresa(
                todos, utilizador["id"], convites, suporte))
        return pagina_config("conta", "<div class='mg-card conf-cx'>" + corpo + "</div>")
    corpo = (
        "<form method='post' action='/configuracoes/conta' class='conf-form'>"
        + _campo("Utilizador", "utilizador", utilizador["email"], extra="disabled")
        + _campo("E-mail de contacto", "contacto", contacto, tipo="email",
                 nota="é para aqui que vai a ligação do «esqueci-me da "
                      "palavra-passe»", extra="autocomplete='email'")
        + _campo("Palavra-passe actual", "actual", "", tipo="password",
                 nota="pede-se para mudar a palavra-passe ou o e-mail",
                 extra="autocomplete='current-password'")
        + _campo("Nova palavra-passe", "nova", "", tipo="password",
                 nota="8 caracteres ou mais; vazia, fica a que está",
                 extra="autocomplete='new-password'")
        + _campo("Repetir a nova palavra-passe", "outra", "", tipo="password",
                 extra="autocomplete='new-password'")
        # secundario: o primario da Conta e o «Criar convite» (UX-7-LEIS V2)
        + "<button type='submit' class='mg-btn mg-btn--secondary'>Guardar</button></form>"
        + "<div class='mg-field__label' style='margin:22px 0 6px'>Sessões abertas</div>"
        + "<div class='saude'>%s</div>" % linhas
        + ("<div style='margin-top:14px'>%s</div>"
           % accao("/sair-de-todos", "Sair de todos os aparelhos", "bt",
                   # G58 da 3.ª ronda: fechava tudo, esta incluída, sem perguntar
                   "Sair de todos os aparelhos? As %d sessões desta conta "
                   "fecham-se, esta também, e volta à entrada." % len(sessoes))
           if sessoes else "")
        # o registo de actividade, só do gestor (2R-§7 (11))
        + ("<p class='nota' style='margin-top:14px'><a href='/actividade'>Actividade "
           "da empresa</a>: quem entrou, de onde, e o que mudou.</p>"
           if da_empresa and sou_admin() else ""))
    corpo += _bloco_do_aspecto(utilizador)
    if contas.pode_ter_segundo_factor(utilizador):
        corpo += _bloco_do_segundo_factor(utilizador)
    if not da_empresa:
        return pagina_config("conta", "<div class='mg-card conf-cx'>" + corpo + "</div>")
    # Três cartões e não um (UX-7-LEIS M2, 1/10/2026): eram seis assuntos
    # num cartão só, e os dados da empresa e a equipa viviam dentro da
    # «Conta» pessoal. O que é de quem está, o que é da empresa, e o
    # registo do suporte, cada um com o seu título.
    return pagina_config("conta", cartao("A minha conta", corpo, id_="a-minha-conta")
                         + _cartoes_da_empresa(todos, utilizador["id"],
                                               convites, suporte))


def _cartoes_da_empresa(todos, eu, convites, suporte):
    """Os dois cartões da Conta que são da empresa, e só do gestor dela:
    a empresa e a equipa, e o registo do suporte (sem entradas, não se
    desenha -- um cartão vazio parecia à espera de carregar)."""
    suporte_html = _bloco_do_suporte(suporte)
    return (cartao("A empresa e a equipa",
                   _bloco_da_empresa() + _bloco_utilizadores(todos, eu)
                   + _bloco_dos_convites(convites), id_="a-empresa")
            + (cartao("Registo do suporte", suporte_html, id_="suporte")
               if suporte_html else ""))


# O que cada aspecto diz a quem escolhe (D14). O escuro oferece-se desde
# a 3.ª ronda (D1): antes saíram os fundos brancos escritos à mão e a banda
# a `--brand`, que o deixavam com texto a 1,16:1 (rel. 06B #3-#7).
ROTULOS_DO_ASPECTO = (
    ("normal", "Normal"),
    ("escuro", "Escuro"),
    # só o nome (30/09/2026, ele): a explicação entre parênteses partia a
    # opção em três linhas, e «como o sistema» já diz o que faz
    ("sistema", "Como o sistema"),
    ("contraste", "Alto contraste"),
)


def _bloco_do_aspecto(utilizador):
    """O aspecto do painel para esta pessoa (D14 da segunda ronda,
    26/09/2026): normal, escuro, como o sistema ou alto contraste. Guarda-se na CONTA e não no
    browser -- quem precisa do contraste precisa dele no telemóvel e no
    computador do escritório, e não tem de o voltar a escolher em cada
    um."""
    actual = utilizador.get("aspecto") or "normal"
    opcoes = "".join(
        "<label class='dist-cx'><input type='radio' name='aspecto' value='%s'%s> %s</label>"
        % (chave, " checked" if chave == actual else "", html.escape(rotulo))
        for chave, rotulo in ROTULOS_DO_ASPECTO)
    return ("<form method='post' action='/configuracoes/conta/aspecto' "
            "class='conf-form' id='aspecto' style='margin-top:22px'>"
            "<fieldset class='dist-interesse'><legend>Aspecto</legend>%s</fieldset>"
            "<div class='nota' style='margin-bottom:10px'>O alto contraste "
            "escurece o texto e as linhas, e tira as sombras. «Como o "
            "sistema» segue o claro ou o escuro que o computador ou o "
            "telemóvel tiverem. Vale para esta conta, em todos os "
            "aparelhos.</div>"
            "<button type='submit' class='mg-btn mg-btn--secondary'>Guardar o aspecto</button>"
            "</form>" % opcoes)


@app.route("/configuracoes/conta/sessoes/terminar", methods=["POST"])
def config_terminar_sessao():
    """Fecha uma sessão da própria conta (G58 da 3.ª ronda). A guarda é a
    da porta -- sessão e CSRF, e no modo de suporte recusa --, e o
    `contas.terminar_sessao()` só fecha as da conta de quem pede."""
    utilizador = g.get("utilizador")
    try:
        n = int(request.form.get("n") or 0)
    except ValueError:
        n = 0
    if not utilizador or not n:
        abort(400)
    with liga() as c:
        fechou = contas.terminar_sessao(c, utilizador["id"], n)
    if fechou:
        registar("", "conta", "terminou uma sessão", quem=utilizador.get("nome"))
    return volta_config("conta", "Sessão terminada." if fechou
                        else "Essa sessão já não estava aberta.")


@app.route("/configuracoes/conta/aspecto", methods=["POST"])
def config_aspecto():
    """Grava o aspecto da pessoa que está (D14). Cada um muda o seu, e
    só o seu: não há `id` no pedido."""
    utilizador = g.get("utilizador")
    if not utilizador:
        return volta_config_erro("conta", "Ainda não há conta.")
    aspecto = (request.form.get("aspecto") or "").strip()
    try:
        with liga() as c:
            contas.gravar_aspecto(c, utilizador["id"], aspecto)
    except ValueError:
        return volta_config_erro("conta", "Esse aspecto não existe.")
    registar("", "conta", "aspecto: %s" % aspecto)
    return volta_config("conta", "Aspecto guardado.")


# ------------------------------------------------ o segundo factor da conta
#
# 28/09/2026, decisão dele: a conta do dono abre a plataforma inteira, e
# bastava a palavra-passe. Opcional, e só do dono por agora
# (`contas.pode_ter_segundo_factor()`); as tabelas e o TOTP estão no
# contas.py. Sem QR: não há biblioteca, e não se acrescenta -- a chave
# vai em texto, para escrever à mão, e como ligação `otpauth://`, que no
# telemóvel abre a app de autenticação.

ANCORA_DO_SEGUNDO_FACTOR = "#segundo-factor"


def _volta_ao_segundo_factor(aviso, erro=False):
    return redirect(volta_config("conta", aviso, erro).location
                    + ANCORA_DO_SEGUNDO_FACTOR)


def _ligacao_otpauth(utilizador, segredo):
    """A ligação que as apps de autenticação conhecem (o formato da Google,
    que todas seguem): o emissor no rótulo e no parâmetro."""
    return ("otpauth://totp/Mira%%20Gov:%s?secret=%s&issuer=Mira%%20Gov"
            % (quote(utilizador["email"], safe="@."), segredo))


def _campo_da_senha_actual():
    return _campo("Palavra-passe actual", "actual", "", tipo="password",
                  extra="autocomplete='current-password' required")


def _campo_do_codigo(nota=""):
    return _campo("Código", "codigo", "", nota=nota,
                  extra="autocomplete='one-time-code' autocapitalize='off' "
                        "spellcheck='false' required")


def _bloco_do_segundo_factor(utilizador):
    """O bloco da Conta, nos três estados: desligado (o botão «Ligar»), a
    meio (a chave e o campo do primeiro código) e ligado (o «Desligar»,
    que pede um código)."""
    with liga() as c:
        ligado = contas.segundo_factor_ligado(c, utilizador["id"])
        segredo = None if ligado else contas.segredo_por_confirmar(c, utilizador["id"])
        faltam = contas.codigos_por_usar(c, utilizador["id"]) if ligado else 0
    cabeca = ("<div class='mg-field__label' id='segundo-factor' "
              "style='margin:22px 0 6px'>Segundo factor</div>")
    if ligado:
        return (cabeca
                + "<p class='nota'>Está <b>ligado</b>. Num aparelho novo, depois "
                  "da palavra-passe, o Mira Gov pede o código da app de "
                  "autenticação. Códigos de recuperação por usar: <b>%d</b>.</p>"
                  % faltam
                + "<form method='post' action='/configuracoes/conta/segundo-factor/"
                  "desligar' class='conf-form'>"
                + _campo_da_senha_actual()
                + _campo_do_codigo("o da app, ou um código de recuperação")
                + "<button type='submit' class='mg-btn'>Desligar o segundo "
                  "factor</button></form>")
    if segredo:
        grupos = " ".join(segredo[i:i + 4] for i in range(0, len(segredo), 4))
        return (cabeca
                + "<ol class='nota'>"
                  "<li>Abra a app de autenticação do telemóvel (Google "
                  "Authenticator, Microsoft Authenticator, ou outra) e "
                  "acrescente uma conta.</li>"
                  "<li>No telemóvel, <a href='%s'>toque aqui para a "
                  "acrescentar</a>. No computador, escolha «introduzir uma "
                  "chave» e escreva esta: <code>%s</code></li>"
                  "<li>Escreva aqui o código de seis dígitos que a app "
                  "mostra.</li></ol>"
                  % (html.escape(_ligacao_otpauth(utilizador, segredo), quote=True),
                     html.escape(grupos))
                + "<form method='post' action='/configuracoes/conta/segundo-factor/"
                  "confirmar' class='conf-form'>"
                + _campo_do_codigo()
                + "<button type='submit' class='mg-btn mg-btn--primary'>Ligar</button>"
                  "</form>"
                + "<div class='nota' style='margin-top:10px'>Só fica ligado "
                  "depois deste código. Até lá, entra como sempre.</div>")
    return (cabeca
            + "<p class='nota'>Com o segundo factor, entrar de um aparelho "
              "novo pede, além da palavra-passe, o código de seis dígitos de "
              "uma app de autenticação no telemóvel. Quem souber a "
              "palavra-passe não entra sem o telemóvel.</p>"
            + "<form method='post' action='/configuracoes/conta/segundo-factor/"
              "ligar' class='conf-form'>"
            + _campo_da_senha_actual()
            + "<button type='submit' class='mg-btn mg-btn--primary'>Ligar o "
              "segundo factor</button></form>")


def _quem_pode_ter_segundo_factor():
    utilizador = g.get("utilizador")
    if not contas.pode_ter_segundo_factor(utilizador):
        abort(403)
    return utilizador


@app.route("/configuracoes/conta/segundo-factor/ligar", methods=["POST"])
def segundo_factor_ligar():
    """Prepara a chave, com a palavra-passe actual (a revisão do PR #123:
    sem ela, uma sessão roubada trancava o dono fora). Não liga nada:
    isso é o `confirmar`."""
    utilizador = _quem_pode_ter_segundo_factor()
    with liga() as c:
        segredo, porque = contas.preparar_segundo_factor(
            c, utilizador["id"], request.form.get("actual") or "",
            ip=request.remote_addr or "")
    if not segredo:
        return _volta_ao_segundo_factor("Não liguei: %s." % porque, erro=True)
    return _volta_ao_segundo_factor("Falta um passo: ponha a chave na app e "
                                    "escreva o primeiro código.")


@app.route("/configuracoes/conta/segundo-factor/confirmar", methods=["POST"])
def segundo_factor_confirmar():
    """Liga com o primeiro código certo, e mostra os códigos de
    recuperação UMA vez (Post/Redirect/Get)."""
    utilizador = _quem_pode_ter_segundo_factor()
    with liga() as c:
        codigos = contas.confirmar_segundo_factor(
            c, utilizador["id"], request.form.get("codigo") or "")
    if not codigos:
        return _volta_ao_segundo_factor(
            "O código não bate com a chave. Confirme que o telemóvel está "
            "na hora certa e escreva o código que a app mostra agora.", erro=True)
    registar_evento("", "conta", "segundo factor ligado: %s" % utilizador["email"],
                    quem=utilizador.get("nome") or "")
    return mostrar_uma_vez(
        "Os códigos de recuperação",
        "O segundo factor está ligado. Se perder o telemóvel, cada um destes "
        "códigos entra <b>uma vez</b> no lugar do da app. Guarde-os fora do "
        "telemóvel (em papel, ou no gestor de palavras-passe). <b>Não se "
        "voltam a ver</b> depois de sair desta página."
        "<ul class='codigos-de-recuperacao'>%s</ul>"
        % "".join("<li><code>%s</code></li>" % html.escape(cod) for cod in codigos),
        " ".join(codigos), "Códigos de recuperação",
        "/configuracoes/conta" + ANCORA_DO_SEGUNDO_FACTOR)


@app.route("/configuracoes/conta/segundo-factor/desligar", methods=["POST"])
def segundo_factor_desligar():
    """Desliga com a palavra-passe actual e um código válido (da app ou de
    recuperação), com trinco (`contas.desligar_com_codigo()`), e leva os
    aparelhos de confiança e os códigos de recuperação."""
    utilizador = _quem_pode_ter_segundo_factor()
    with liga() as c:
        usado, porque = contas.desligar_com_codigo(
            c, utilizador["id"], request.form.get("actual") or "",
            request.form.get("codigo") or "", ip=request.remote_addr or "")
    if not usado:
        registar_evento("", "conta", "segundo factor: não desligou (%s): %s"
                        % (utilizador["email"], porque), quem=utilizador.get("nome") or "")
        return _volta_ao_segundo_factor("Não desliguei: %s. Nada mudou." % porque,
                                        erro=True)
    registar_evento("", "conta", "segundo factor desligado: %s%s"
                    % (utilizador["email"], " (com um código de recuperação)"
                       if usado == "recuperacao" else ""),
                    quem=utilizador.get("nome") or "")
    return _volta_ao_segundo_factor("Segundo factor desligado. Os aparelhos de "
                                    "confiança e os códigos de recuperação "
                                    "deixaram de servir.")


def _bloco_da_empresa(cfg=None):
    """Quem somos nós, para o cruzamento com o Portal BASE.

    Sem isto o radar sabe a quem o procedimento foi adjudicado mas não
    sabe se esse alguém somos nós -- e pergunta, em vez de adivinhar. Com
    o NIF preenchido, adianta a resposta; o gesto de fechar continua a
    ser de quem lê (etapa 4 do `docs/historico/CRM.md`).

    O NIF, e não só o nome: o dump do IMPIC traz o NIF do adjudicatário,
    e um nome de empresa escreve-se de cinco maneiras («LDA», «Lda.»,
    «, S.A.») -- comparar por nome sozinho dava falsos negativos
    justamente nos concursos que interessam.
    """
    nome, nif = _nome_da_empresa(cfg)
    # Recusado o NIF, o que se escreveu volta ao formulário (E61): o nome
    # novo voltava ao antigo, e perdia-se.
    if has_request_context() and request.args.get("tom") == "erro":
        nome = request.args.get("nome_da_empresa", nome)
        nif = request.args.get("nif_da_empresa", nif)
    return ("<div class='mg-field__label' id='empresa' style='margin:22px 0 6px'>A nossa empresa</div>"
            "<div class='nota' style='margin-bottom:10px'>Para o Mira Gov saber, "
            "ao cruzar com o Portal BASE, se a adjudicação foi nossa. "
            "Enquanto estiver vazio, a ficha mostra a quem foi e pergunta."
            "</div>"
            "<form method='post' action='/configuracoes/conta/empresa' "
            "class='conf-form'>"
            + _campo("Nome", "nome_da_empresa", nome,
                     nota="como aparece nos contratos", extra="maxlength='120'")
            + _campo("NIF", "nif_da_empresa", nif,
                     nota="nove dígitos; é por aqui que a ligação é certa",
                     extra="inputmode='numeric' maxlength='14' autocomplete='off'")
            + "<button type='submit' class='mg-btn mg-btn--secondary'>Guardar</button></form>")


@app.route("/configuracoes/conta/empresa", methods=["POST"])
def config_empresa():
    """Grava quem somos nós. O NIF fica só com os dígitos: o dump do
    IMPIC guarda-o assim, e um espaço ou um ponto a meio fazia a
    comparação falhar sem nada no ecrã a dizer porquê."""
    nome = " ".join((request.form.get("nome_da_empresa") or "").split())
    # sem nome a empresa desaparecia do topo da barra (5.ª ronda)
    if not nome:
        return volta_config_erro("conta", "Escreva o nome da empresa. Nada "
                                 "foi guardado.")
    if len(nome) > 120:
        return volta_config_erro("conta", "O nome da empresa tem até 120 "
                                 "letras (tem %d). Nada foi guardado." % len(nome))
    # sem o [:9] de antes: cortar um NIF de dez dígitos dava outro NIF,
    # e o dígito de controlo é o que apanha a gralha
    nif, recado = problema_do_nif(request.form.get("nif_da_empresa"))
    if recado:
        return redirect("/configuracoes/conta?%s#empresa" % urlencode({
            "aviso": recado + " Nada foi guardado.",
            "tom": "erro", "nome_da_empresa": nome,
            "nif_da_empresa": request.form.get("nif_da_empresa") or ""}))
    gravar_config_registado({"nome_da_empresa": nome, "nif_da_empresa": nif})
    return volta_config("conta", "A nossa empresa: guardada.")


def _documento_do_pedido(form):
    """((tipo, descricao, validade ISO ou None), recado) do formulário de
    um documento do cofre. A validade que não se lê recusa-se: gravá-la
    vazia era perder a tarefa sem dizer nada."""
    tipo = (form.get("tipo") or "").strip()
    if tipo not in TIPOS_DE_DOCUMENTO:
        return None, "Escolha o tipo de documento da lista."
    descricao = texto_de_campo(form.get("descricao"), 120)
    bruta = " ".join((form.get("validade") or "").split())
    validade = data_de_filtro(bruta) if bruta else None
    if validade and not (ANOS_QUE_SE_ESCREVEM[0] <= int(validade[:4])
                         <= ANOS_QUE_SE_ESCREVEM[1]):
        validade = None
    if bruta and not validade:
        return None, "«%s» não é uma data (dd/mm/aaaa)." % corta(bruta, 20)
    # vazio nas duas não diz que documento é (5.ª ronda: ficava um
    # «Alvará» sem número e sem validade)
    if not descricao and not validade:
        return None, ("Escreva o número ou a descrição do documento, ou a "
                      "validade. Nada foi guardado.")
    return (tipo, descricao, validade), ""


@app.route("/configuracoes/documentos", methods=["GET", "POST"])
def config_documentos():
    """O cofre dos documentos da empresa (D5 da segunda ronda,
    26/09/2026): o tipo, o número ou a descrição, e a validade. Sem
    ficheiros. Cada validade dá uma tarefa 15 dias antes
    (`sincronizar_documentos()`). Só o admin da empresa (ROTAS_SO_ADMIN).
    Em todos os planos: o cofre fechava no Solo até os planos passarem a
    ter todos o mesmo (1/10/2026)."""
    if request.method == "POST":
        doc, recado = _documento_do_pedido(request.form)
        if recado:
            return volta_config("documentos", recado, erro=True)
        with liga() as c:
            c.execute("INSERT INTO documentos_da_empresa (tipo, descricao, "
                      "validade, criado_em) VALUES (?,?,?,?)",
                      doc + (datetime.now().strftime("%Y-%m-%d %H:%M"),))
        registar("", "documento", "%s %s: válido até %s"
                 % (doc[0], doc[1], data_pt(doc[2], "sem validade")))
        sincronizar_documentos(quem=minha_conta())
        return volta_config("documentos", "Documento guardado.")
    with liga() as c:
        docs = c.execute("SELECT * FROM documentos_da_empresa ORDER BY "
                         "COALESCE(validade, '9999'), id").fetchall()
    hoje = datetime.now().date().isoformat()

    def opcoes(actual):
        return "".join("<option%s>%s</option>"
                       % (" selected" if t == actual else "", html.escape(t))
                       for t in TIPOS_DE_DOCUMENTO)

    def estado(d):
        if not d["validade"]:
            return "<span class='mg-tag'>sem validade</span>"
        if d["validade"] < hoje:
            return "<span class='mg-tag mg-tag--danger'>caducado</span>"
        aviso = tarefa_do_documento(d)[0]
        if aviso <= hoje:
            return "<span class='mg-tag mg-tag--warning'>a caducar</span>"
        return "<span class='mg-tag mg-tag--success'>válido</span>"
    linhas = "".join(
        "<tr><td>%s</td><td><form class='doc-linha' method='post' "
        "action='/configuracoes/documentos/%d'>"
        "<select name='tipo' aria-label='Tipo'>%s</select>"
        "<input type='text' name='descricao' value='%s' maxlength='120' "
        "aria-label='Número ou descrição' placeholder='n.º ou descrição'>"
        "<input type='text' name='validade' value='%s' inputmode='numeric' "
        "maxlength='10' placeholder='dd/mm/aaaa' aria-label='Válido até' "
        "pattern='\\d{1,2}/\\d{1,2}/\\d{4}'>"
        "<button type='submit' class='mg-btn mg-btn--sm mg-btn--secondary'>"
        "Guardar</button></form></td><td>%s</td></tr>"
        % (estado(d), d["id"], opcoes(d["tipo"]),
           html.escape(d["descricao"] or "", quote=True),
           html.escape(data_pt(d["validade"], ""), quote=True),
           accao("/configuracoes/documentos/%d/apagar" % d["id"], "Remover",
                 "mini perigo", "Remover «%s %s»? A tarefa dele sai também."
                 % (d["tipo"], d["descricao"] or ""),
                 rotulo="Remover «%s %s»" % (d["tipo"], d["descricao"] or "")))
        for d in docs)
    tabela = ("<table class='mg-table tab-docs'><thead><tr><th>Estado</th>"
              "<th>Documento e validade</th><th></th></tr></thead>"
              "<tbody>%s</tbody></table>" % linhas) if docs else (
        "<p class='nota'>Ainda não há documentos na lista.</p>")
    novo = ("<form method='post' class='conf-form' style='margin-top:18px'>"
            "<label class='conf-campo'><span>Tipo</span><select name='tipo'>"
            "%s</select></label>%s%s"
            # «Adicionar», como nos contactos e nas tarefas (5.ª ronda; era
            # «Acrescentar», e antes «Juntar», E14)
            "<button type='submit' class='mg-btn mg-btn--primary'>Adicionar"
            "</button></form>"
            % (opcoes(""), _campo("Número ou descrição", "descricao", "",
                                  extra="maxlength='120'"),
               _campo("Válido até", "validade", "",
                      nota="dd/mm/aaaa; vazio se não caduca",
                      extra="inputmode='numeric' maxlength='10' "
                            "placeholder='dd/mm/aaaa'")))
    return pagina_config("documentos", (
        # sem a primeira frase, que repetia o subtitulo da banda (E14)
        "<div class='mg-card conf-cx'><p class='nota'>Os ficheiros "
        "ficam onde a empresa os tem: aqui fica o que caduca. %d dias "
        "antes de cada validade nasce uma tarefa no Hoje, e mudar a "
        "validade troca-a pela da data nova.</p>%s%s</div>"
        % (DIAS_ANTES_DA_VALIDADE, tabela, novo)))


@app.route("/configuracoes/documentos/<int:id_>", methods=["POST"])
def config_documento_gravar(id_):
    doc, recado = _documento_do_pedido(request.form)
    if recado:
        return volta_config("documentos", recado, erro=True)
    with liga() as c:
        mudou = c.execute("UPDATE documentos_da_empresa SET tipo=?, descricao=?, "
                          "validade=? WHERE id=?", doc + (id_,)).rowcount
    # um documento que já não existe não se dá por guardado (5.ª ronda)
    if not mudou:
        return volta_config("documentos", "Esse documento já não existe: "
                            "nada foi guardado.", erro=True)
    registar("", "documento", "%s %s: válido até %s"
             % (doc[0], doc[1], data_pt(doc[2], "sem validade")))
    sincronizar_documentos(quem=minha_conta())
    return volta_config("documentos", "Documento guardado.")


@app.route("/configuracoes/documentos/<int:id_>/apagar", methods=["POST"])
def config_documento_apagar(id_):
    with liga() as c:
        saiu = c.execute("DELETE FROM documentos_da_empresa WHERE id=?",
                         (id_,)).rowcount
    if not saiu:
        return volta_config("documentos", "Esse documento já não existia.",
                            erro=True)
    sincronizar_documentos()          # leva as tarefas dele
    return volta_config("documentos", "Documento removido.")


# Os papéis como o ecrã os diz (segunda ronda, glossário do revisor de
# texto): «admin» e «tester» são as chaves gravadas, em inglês, e o
# «tester» nem dizia o que a conta faz.
# «Membro» e não «Utilizador» (6.ª ronda, decisão dele a 6/10/2026): na
# Conta, «Utilizador» era também o nome com que se entra
PAPEL_NO_ECRA = {"admin": "Gestor", "tester": "Membro"}


def papel_no_ecra(papel):
    return PAPEL_NO_ECRA.get(papel, papel or "")


def _bloco_utilizadores(todos, eu):
    """A gestao das contas, so ao admin (13/09/2026): quem existe, de que
    tipo, e o formulario para criar outra. Tirar uma conta e um botao
    com confirmacao; o ultimo admin nao se tira (contas.apagar_utilizador
    recusa)."""
    linhas = "".join(
        # o nome da pessoa ao lado do utilizador, e a bolinha diz o que é
        # (5.ª ronda: só o «qa4-03», e um ponto verde sem legenda)
        "<div class='l'><span class='ponto' style='background:%s' title='%s' "
        "aria-hidden='true'></span>"
        "<span class='t'>%s%s</span><span class='v'>%s%s</span></div>"
        % ("var(--success)" if u["papel"] == "admin" else "var(--line-strong)",
           html.escape(papel_no_ecra(u["papel"]), quote=True),
           html.escape(("%s · %s" % (u["nome"], u["email"]))
                       if (u["nome"] or "").strip() and u["nome"] != u["email"]
                       else u["email"]),
           " (eu)" if u["id"] == eu else "",
           html.escape(papel_no_ecra(u["papel"])),
           "" if u["id"] == eu else
           (" &middot; " + accao("/configuracoes/conta/utilizadores/%d/repor" % u["id"],
                                 "repor palavra-passe", "mini",
                                 rotulo="Gerar a ligação para repor a "
                                 "palavra-passe de %s" % u["email"])
            if contas.pode_repor(g.get("utilizador"), u) else "")
           # o «tirar» so a quem o pode fazer: a conta do dono so o
           # dono a tira (contas.apagar_utilizador recusa na mesma)
           + (" &middot; " + accao("/configuracoes/conta/utilizadores/%d/apagar" % u["id"],
                                   "Remover", "mini perigo",
                                   "Remover a conta %s? As sessões dela fecham já."
                                   % html.escape(u["email"], quote=True),
                                   # onze «Remover» seguidos não diziam de
                                   # quem (3.ª ronda, G67)
                                   rotulo="Remover %s da empresa" % u["email"])
              if contas.pode_repor(g.get("utilizador"), u) else ""))
        for u in todos)
    return (
        "<div class='mg-field__label' style='margin:26px 0 6px'>Utilizadores</div>"
        "<div class='nota' style='margin-bottom:10px'><b>Gestor</b>: "
        "gere as contas e os dados da empresa. <b>Utilizador</b>: trabalha "
        "nos concursos e nas propostas, sem mexer nas contas.</div>"
        "<div class='saude contas-da-empresa'>%s</div>"
        # O convite primeiro (teste com utilizadores, 25/09/2026): criar a
        # conta obrigava o admin a inventar a palavra-passe do colega e a
        # manda-la por algum lado. Com o convite, e o colega que a escolhe.
        "<form method='post' action='/configuracoes/conta/utilizadores/convite' "
        "class='conf-form' id='convidar' style='margin-top:16px'>"
        "<div class='nota' style='flex:1 1 100%%'><b>Convidar um colega</b>: "
        "cria-se uma ligação, manda-se ao colega, e é ele que escolhe o nome "
        "e a palavra-passe. Vale %d dias, e só uma vez. Com o e-mail dele, "
        "o convite segue por e-mail.</div>"
        "<label class='conf-campo'><span>E-mail <span class='nota'>(opcional)"
        "</span></span><input type='email' name='email' autocomplete='off' "
        "placeholder='nome@empresa.pt'></label>"
        "<label class='conf-campo'><span>Papel</span><select name='papel'>"
        "<option value='tester'>Membro</option>"
        "<option value='admin'>Gestor</option></select></label>"
        "<button type='submit' class='mg-btn mg-btn--primary'>Criar convite</button></form>"
        # O segundo caminho recolhido (UX-7-LEIS, H2 e V2, 30/09/2026):
        # eram dois caminhos a vista para a mesma coisa, e dois botoes
        # cheios; o convite e o caminho, e este fica para quem o procura.
        "<details class='mg-disc' style='margin-top:18px'><summary class='nota'>"
        "Criar sem convite, já com a palavra-passe</summary>"
        "<form method='post' action='/configuracoes/conta/utilizadores' "
        "class='conf-form' style='margin-top:8px'>"
        "%s%s"
        "<label class='conf-campo'><span>Papel</span><select name='papel'>"
        "<option value='tester'>Membro</option>"
        "<option value='admin'>Gestor</option></select></label>"
        "<button type='submit' class='mg-btn mg-btn--secondary'>Criar utilizador</button>"
        "</form></details>"
        % (linhas, contas.DIAS_DE_CONVITE,
           _campo("E-mail", "email", "", tipo="email",
                  extra="autocomplete='off' placeholder='nome@empresa.pt' required"),
           _campo("Palavra-passe", "senha", "", tipo="password",
                  nota="8 caracteres ou mais",
                  extra="autocomplete='new-password'")))


def _bloco_dos_convites(convites):
    """Os convites da empresa que ninguem usou, com o «anular» (a pagina
    do dono, 26/09/2026): um convite que foi para o endereco errado
    esperava sete dias. O dono ve e anula os de todas, na /plataforma."""
    if not convites:
        return ""
    agora = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    return ("<div class='mg-field__label' id='convites' style='margin:22px 0 6px'>"
            "Convites por usar</div><div class='saude'>%s</div>" % "".join(
                "<div class='l'><span class='t'>%s, de %s, criado a %s</span>"
                "<span class='v'>%s &middot; %s</span></div>"
                % (html.escape(cv["email"] or "sem endereço"),
                   html.escape(papel_no_ecra(cv["papel"]).lower()),
                   html.escape(data_hora_pt(cv["criado_em"][:16])),
                   "acabou" if cv["expira"] <= agora else
                   "vale até %s" % html.escape(data_hora_pt(cv["expira"][:16])),
                   accao("/configuracoes/conta/utilizadores/convites/%d/anular" % cv["id"],
                         "anular", "mini cuidado",
                         "Anular este convite? A ligação deixa de servir.",
                         rotulo="Anular o convite de %s" % (cv["email"] or "sem endereço")))
                for cv in convites))


def _bloco_do_suporte(linhas):
    """Quando o dono da plataforma entrou para ver a empresa, e saiu (o
    modo de suporte, 26/09/2026): o admin tem de saber quem viu o
    trabalho da empresa, e quando."""
    if not linhas:
        return ""
    return ("<div class='mg-field__label' style='margin:22px 0 6px'>Acessos do "
            "suporte</div><div class='nota' style='margin-bottom:8px'>O dono da "
            "plataforma pode ver a aplicação como a empresa a vê, só para ler, "
            "para responder a um pedido de ajuda. Cada entrada fica aqui.</div>"
            "<div class='saude'>%s</div>" % "".join(
                "<div class='l'><span class='t'>%s</span><span class='v'>%s</span></div>"
                % (html.escape(l["detalhe"] or ""), html.escape(data_hora_pt(l["quando"])))
                for l in linhas))


@app.route("/configuracoes/conta/utilizadores/convites/<int:convite_id>/anular",
           methods=["POST"])
def conta_anular_convite(convite_id):
    """O admin anula um convite da empresa dele; um de outra empresa e
    como se nao existisse (404)."""
    with liga() as c:
        convite = contas.anular_convite(c, convite_id, empresa_activa())
    if not convite:
        abort(404)
    registar("", "conta", "anulou o convite de %s para %s"
             % (convite["papel"], convite["email"] or "sem endereço"))
    return volta_config("conta", "Convite anulado.")


@app.route("/configuracoes/conta/utilizadores", methods=["POST"])
def conta_criar_utilizador():
    email = (request.form.get("email") or "").strip()
    papel = (request.form.get("papel") or "tester").strip()
    with liga() as c:
        if c.execute("SELECT 1 FROM utilizadores WHERE email=?",
                     (contas.email_limpo(email),)).fetchone():
            return volta_config_erro("conta", "Já existe um utilizador %s." % email)
        # o limite do plano também aqui (5.ª ronda: num Solo o convite era
        # recusado, e o «criar sem convite» fazia a 2.ª, a 3.ª conta)
        if contas.lugares_livres(c, empresa_activa()) == 0:
            return volta_config_erro("conta", "O utilizador não foi criado: %s"
                                     % contas.frase_do_limite(c, empresa_activa()))
        try:
            contas.criar_conta(c, email, request.form.get("senha") or "",
                                    papel=papel, empresa_id=empresa_activa())
        except ValueError as erro:
            return volta_config_erro("conta", "O utilizador não foi criado: %s." % erro)
    registar("", "conta", "criou o utilizador %s (%s)"
             % (contas.email_limpo(email), papel))
    return volta_config("conta", "Utilizador %s criado, como %s."
                        % (contas.email_limpo(email), papel_no_ecra(papel)))


