# Os tokens da aplicação e o tema «como o sistema» (3.ª ronda, D11): o
# site tinha uma paleta e uma letra suas, e um escuro seu que não era o
# da aplicação. Os tokens vão num <style> e não na folha da aplicação:
# são 3 KB, e a folha inteira traria as classes dela (.ficha, .cartao,
# .aba) a chocar com as do site. Lidos no arranque, como o CSS_TUDO.
TOKENS_DO_SITE = ler_estilo("miragov-tokens.css")


def ritmo_da_verificacao(horas):
    """(«De hora a hora», «das 8h às 20h»): como o site diz quando se
    verifica, a partir do `horas_verificacao` (3.ª ronda, G101: dizia
    «Todo o dia», escrito à mão, e o `/entrar` mostrava a última recolha
    às 20h)."""
    hs = sorted({int(h[:2]) for h in horas if h[:2].isdigit()})
    if not hs:
        return "Ao longo do dia", "verificação automática"
    if len(hs) > 2 and hs == list(range(hs[0], hs[-1] + 1)):
        return "De hora a hora", "das %dh às %dh, verificação automática" % (
            hs[0], hs[-1])
    vezes = "Uma vez por dia" if len(hs) == 1 else "%d vezes por dia" % len(hs)
    return vezes, "às %s, verificação automática" % " e às ".join(
        "%dh" % h for h in hs)


def numero_do_site(n):
    """«200 000+»: o número de concursos do `/entrar`, arredondado para
    baixo ao milhar, para não mentir a quem clica em «Entrar» e vê o
    exacto (3.ª ronda, G101)."""
    if n < 1000:
        return mil_pt(n)
    return mil_pt(n // 1000 * 1000) + "<small>+</small>"


def faq_em_json_ld(texto):
    """O `FAQPage` do Schema.org, tirado das perguntas que a página
    MOSTRA (os `<details>`, 29/09/2026). Não se escreve à mão no
    `<head>`: seria o mesmo texto em dois sítios, e o Google trata como
    abuso um FAQ nos dados que não é o que está no ecrã. Sem perguntas,
    nada."""
    def limpo(s):
        return " ".join(html.unescape(re.sub(r"<[^>]+>", "", s)).split())
    pares = re.findall(r"<details[^>]*>\s*<summary>(.*?)</summary>\s*"
                       r"<p>(.*?)</p>", texto, flags=re.S)
    if not pares:
        return ""
    dados = {"@context": "https://schema.org", "@type": "FAQPage",
             "mainEntity": [{"@type": "Question", "name": limpo(p),
                             "acceptedAnswer": {"@type": "Answer",
                                                "text": limpo(r)}}
                            for p, r in pares]}
    # «</» dentro de um <script> fechava-o antes do tempo
    return ('<script type="application/ld+json">%s</script>'
            % json.dumps(dados, ensure_ascii=False).replace("</", "<\\/"))


# Quantos prazos tem cada dia útil da fita de exemplo, pela ordem em que
# aparecem; o fim de semana tem sempre zero.
PRAZOS_DO_EXEMPLO = (3, 1, 4, 2, 5)


def datas_do_exemplo(texto, hoje=None):
    """As datas dos ecrãs de exemplo do site, contadas a partir de hoje
    (auditoria de 30/09/2026). Estavam escritas à mão: um dia depois de
    publicadas, o prazo «28/09 · 6 dias» já tinha passado, e o Hoje de
    exemplo dizia «Terça, 22 de Setembro» -- um site parado no tempo.

    `{{DATA+6}}` dá 06/10/2026, `{{DATA+6:curta}}` dá 06/10,
    `{{HOJE_EXTENSO}}` o título do Hoje, e `{{FITA_EXEMPLO}}` a fita,
    que começa ontem como a da aplicação. Os meses em minúscula: o site
    está no Acordo Ortográfico, a aplicação não."""
    hoje = hoje or datetime.now().date()

    def data(m):
        d = hoje + timedelta(days=int(m.group(1)))
        return d.strftime("%d/%m" if m.group(2) else "%d/%m/%Y")
    texto = re.sub(r"\{\{DATA([+-]\d+)(:curta)?\}\}", data, texto)
    texto = texto.replace("{{HOJE_EXTENSO}}", "%s, %d de %s" % (
        DIAS_LONGOS[hoje.weekday()], hoje.day,
        MESES_LONGOS[hoje.month - 1].lower()))
    if "{{FITA_EXEMPLO}}" in texto:
        celulas, uteis = [], 0
        for i in range(-1, 6):
            d = hoje + timedelta(days=i)
            n = 0
            if d.weekday() < 5:
                n = PRAZOS_DO_EXEMPLO[uteis % len(PRAZOS_DO_EXEMPLO)]
                uteis += 1
            celulas.append(
                '<div class="dia%s"%s><b>%s</b><span class="num">%d</span>'
                '<i>%s</i></div>'
                % (" cheio" if n >= 4 else "",
                   ' aria-current="true"' if i == 0 else "",
                   DIAS_CURTOS[d.weekday()].capitalize(), n,
                   "prazo" if n == 1 else "prazos" if n else "&nbsp;"))
        texto = texto.replace("{{FITA_EXEMPLO}}", "".join(celulas))
    return texto


# ------------------------------------------------------------------ visitas
#
# A medição das visitas ao site (ANL, pedido dele a 4/10/2026): sem
# cookies, sem serviços de terceiros e sem guardar o IP. O servidor grava
# a página quando a serve (`registar_visita()`, pelo `_do_site()`), e um
# beacon pequeno junta o tempo, o scroll e o que se fez (`/visita`).

MESES_DAS_VISITAS = 13
DIAS_DAS_VISITAS = 365 + 31          # os 13 meses, contados por baixo
# Os robôs pelo nome que dão a si próprios; os que mentem passam, mas
# não mandam o beacon, e o painel separa as visitas com e sem JavaScript.
RX_ROBO = re.compile(r"bot\b|bot/|crawl|spider|slurp|preview|facebookexternalhit|"
                     r"headless|python|curl|wget|httpclient|okhttp|go-http|"
                     r"monitor|lighthouse|uptime|scrapy|java/", re.I)
EVENTOS_DA_VISITA = {"clique": "Clicaram em «Pedir acesso»",
                     "form": "Começaram o formulário",
                     "enviado": "Enviaram o pedido",
                     "precos": "Chegaram aos preços"}
RX_ID_DA_VISITA = re.compile(r"[0-9a-f]{16}")
TECTO_DO_BEACON = 2048
# O sal do dia, só em memória: com ele o mesmo visitante conta uma vez por
# dia, e ninguém -- nem quem tiver a base -- volta do resumo ao IP. Ao
# virar o dia faz-se outro, e as visitas de mais de MESES_DAS_VISITAS
# meses saem. Ponytail: um reinício a meio do dia faz outro sal, e quem
# voltar depois conta duas vezes nesse dia -- aceite.
_SAL_DAS_VISITAS = {}


def _sal_de_hoje():
    hoje = date.today().isoformat()
    if _SAL_DAS_VISITAS.get("dia") != hoje:
        _SAL_DAS_VISITAS.update(dia=hoje, sal=os.urandom(16))
        limite = (date.today() - timedelta(days=DIAS_DAS_VISITAS)).isoformat()
        with liga() as c:
            c.execute("DELETE FROM visitas WHERE dia < ?", (limite,))
    return _SAL_DAS_VISITAS["sal"]


def _de_onde_veio():
    """Só o domínio de onde veio, sem o resto do endereço («linkedin.com»),
    e vazio quando veio de dentro do site ou de lado nenhum."""
    nome = (urlparse(request.headers.get("Referer") or "").hostname or "").lower()
    if nome.startswith("www."):
        nome = nome[4:]
    if not nome or nome_de_anfitriao(nome) == nome_de_anfitriao(
            (request.host or "").split(":")[0]) or nome in DOMINIOS_DO_PAINEL:
        return ""
    return nome[:80]


def registar_visita():
    """O `id` da visita desta página do site, ou "" quando não conta: um
    robô, quem tem sessão (o dono e os clientes) ou o próprio PC."""
    if not has_request_context():      # a página montada fora de um pedido
        return ""
    agente = request.headers.get("User-Agent") or ""
    if (request.method != "GET" or not agente or RX_ROBO.search(agente)
            or com_sessao() or pedido_e_local()):
        return ""
    try:
        sal = _sal_de_hoje()
        visitante = hmac.new(sal, ("%s|%s" % (ip_de_quem_pede(), agente)).encode(),
                             hashlib.sha256).hexdigest()[:16]
        id_ = os.urandom(8).hex()
        agora = datetime.now()
        a = request.args
        with liga() as c:
            c.execute("INSERT INTO visitas (id, quando, dia, caminho, origem, utm_fonte, "
                      "utm_meio, utm_campanha, visitante, aparelho) "
                      "VALUES (?,?,?,?,?,?,?,?,?,?)",
                      (id_, agora.strftime("%Y-%m-%d %H:%M:%S"), agora.date().isoformat(),
                       request.path[:120], _de_onde_veio(),
                       (a.get("utm_source") or "")[:60], (a.get("utm_medium") or "")[:60],
                       (a.get("utm_campaign") or "")[:60], visitante,
                       aparelho_do_agente(agente)))
        return id_
    except sqlite3.Error:
        return ""        # a medição nunca tira o site do ar


# O beacon: o tempo com a página à vista, o scroll mais fundo e os quatro
# eventos. Manda ao esconder a página (e ao sair); o servidor fica com o
# maior de cada um, por isso mandar duas vezes não estraga nada.
BEACON_DA_VISITA = """<script>(function(){var V="%s",vis=0,ini=document.visibilityState=="visible"?Date.now():0,max=0,ev={};
function sc(){var h=document.documentElement,p=Math.round(100*(window.scrollY+window.innerHeight)/Math.max(h.scrollHeight,1));if(p>max)max=Math.min(p,100)}
addEventListener("scroll",sc,{passive:true});sc();
document.addEventListener("click",function(e){var a=e.target.closest&&e.target.closest('a[href$="#acesso"]');if(a)ev.clique=1});
var f=document.getElementById("form-acesso");if(f){f.addEventListener("focusin",function(){ev.form=1});var c=f.querySelector('input[name="vista"]');if(c)c.value=V}
var pl=document.getElementById("planos");if(pl&&window.IntersectionObserver)new IntersectionObserver(function(es){es.forEach(function(x){if(x.isIntersecting)ev.precos=1})}).observe(pl);
function manda(){if(ini){vis+=Date.now()-ini;ini=0}if(navigator.sendBeacon)navigator.sendBeacon("/visita",JSON.stringify({v:V,s:Math.round(vis/1000),p:max,e:Object.keys(ev)}))}
document.addEventListener("visibilitychange",function(){if(document.visibilityState=="hidden")manda();else ini=Date.now()});
addEventListener("pagehide",manda)})();</script>"""


def _com_o_beacon(texto):
    id_ = registar_visita()
    if not id_:
        return texto
    return texto.replace("</body>", BEACON_DA_VISITA % id_ + "</body>", 1)


def marcar_evento_da_visita(id_, eventos, segundos=0, scroll=0, com_js=False):
    """Junta à visita `id_` o que veio (o beacon, ou o pedido enviado): o
    maior tempo e scroll, os eventos da lista branca. Uma visita de mais
    de seis horas, ou que não existe, não muda."""
    if not RX_ID_DA_VISITA.fullmatch(id_ or ""):
        return
    desde = (datetime.now() - timedelta(hours=6)).strftime("%Y-%m-%d %H:%M:%S")
    with liga() as c:
        v = c.execute("SELECT eventos FROM visitas WHERE id=? AND quando >= ?",
                      (id_, desde)).fetchone()
        if not v:
            return
        juntos = set(filter(None, (v["eventos"] or "").split("|"))) | (
            set(eventos) & set(EVENTOS_DA_VISITA))
        c.execute("UPDATE visitas SET segundos=MAX(segundos, ?), scroll=MAX(scroll, ?), "
                  "eventos=?, com_js=MAX(com_js, ?) WHERE id=?",
                  (segundos, scroll, ("|%s|" % "|".join(
                      k for k in EVENTOS_DA_VISITA if k in juntos)) if juntos else "",
                   1 if com_js else 0, id_))


@app.route("/visita", methods=["POST"])
def visita():
    """O beacon do site. Rota ABERTA (quem visita não tem conta), e a
    guarda é esta: a origem (`origem_e_nossa()`), o tamanho do corpo, o
    `id` da visita (16 hexadecimais, e só uma visita das últimas seis
    horas muda) e os números cortados. Responde 204 sempre que não é
    abuso, para não dizer que `id`s existem."""
    if not origem_e_nossa():
        return Response("", 403)
    if (request.content_length or 0) > TECTO_DO_BEACON:
        return Response("", 413)
    try:
        d = json.loads(request.get_data(as_text=True)[:TECTO_DO_BEACON] or "{}")
        marcar_evento_da_visita(
            str(d.get("v") or ""), [str(e) for e in (d.get("e") or [])][:10],
            segundos=max(0, min(int(d.get("s") or 0), 3 * 3600)),
            scroll=max(0, min(int(d.get("p") or 0), 100)), com_js=True)
    except (ValueError, TypeError, AttributeError):
        pass
    return Response("", 204)


# ---------------------------------------------------------------------- uso
#
# O uso da aplicação pelas contas das empresas (ANL, o grupo E, desenho
# aceite por ele a 4/10/2026): para o dono ver quem encravou e ajudar por
# e-mail, sem dizer ao cliente o pormenor. Só a rota (a regra do Flask, sem
# os valores), o método e a conta; nada do que se escreveu.

# Os percursos que se seguem: (nome, a página onde começa, as gravações que
# o acabam). Começado e não acabado = abriu o início depois da última vez
# que gravou o fim.
PERCURSOS_DO_USO = (
    ("O perfil da empresa", "/configuracoes/interesse", ("/alertas/interesse",)),
    ("Criar um alerta", "/configuracoes/alertas", ("/alertas/criar", "/alertas/do-perfil")),
    ("Importar o histórico", "/configuracoes/importar", ("/configuracoes/importar/confirmar",)),
    ("Os documentos da empresa", "/configuracoes/documentos", ("/configuracoes/documentos",)),
    ("Criar uma proposta", "/proposta/nova", ("/proposta/nova",)),
)
DIAS_DO_USO = 365 + 31               # os 13 meses, como as visitas
PREFIXOS_FORA_DO_USO = ("/tipo", "/estilo", "/favicon", "/visita", "/saude",
                        "/marca", "/robots", "/sitemap")
_PODA_DO_USO = {}


@app.after_request
def registar_uso(resposta):
    """Uma linha no `uso` por página que uma conta de empresa abre ou
    grava. Não contam o dono (nem no modo de suporte), as respostas de
    erro e os ficheiros que a página pede. Nunca estraga a resposta."""
    try:
        regra = request.url_rule.rule if request.url_rule else ""
        u = g.get("utilizador")
        if (not regra or not u or contas.e_dono(u) or resposta.status_code >= 400
                or request.method not in ("GET", "POST")
                or regra.startswith(PREFIXOS_FORA_DO_USO)):
            return resposta
        agora = datetime.now()
        with liga() as c:
            if _PODA_DO_USO.get("dia") != agora.date().isoformat():
                _PODA_DO_USO["dia"] = agora.date().isoformat()
                c.execute("DELETE FROM uso WHERE dia < ?", (
                    (agora.date() - timedelta(days=DIAS_DO_USO)).isoformat(),))
            c.execute("INSERT INTO uso VALUES (?,?,?,?,?,?)",
                      (agora.strftime("%Y-%m-%d %H:%M:%S"), agora.date().isoformat(),
                       u["id"], u.get("empresa_id"), regra[:120], request.method))
    except (sqlite3.Error, RuntimeError, KeyError):
        pass
    return resposta


def uso_da_empresa(id_, dias=30):
    """(contas, por_acabar) da empresa nos últimos `dias`: por conta, os
    dias em que entrou, a última vez e as páginas que mais abriu; e os
    percursos começados e não acabados, por conta, com quantas vezes."""
    desde = (date.today() - timedelta(days=dias)).isoformat()
    with liga() as c:
        linhas = c.execute(
            "SELECT c.email, u.quando, u.dia, u.rota, u.metodo FROM uso u "
            "JOIN utilizadores c ON c.id = u.utilizador_id "
            "WHERE u.empresa_id=? AND u.dia >= ? ORDER BY u.quando", (id_, desde)).fetchall()
    por_conta = {}
    for l in linhas:
        por_conta.setdefault(l["email"], []).append(l)
    contas_, por_acabar = [], []
    for email, ls in sorted(por_conta.items()):
        paginas = Counter(l["rota"] for l in ls if l["metodo"] == "GET")
        contas_.append({"email": email, "dias": len({l["dia"] for l in ls}),
                        "ultima": ls[-1]["quando"],
                        "paginas": [r for r, _ in paginas.most_common(3)]})
        for nome, inicio, fins in PERCURSOS_DO_USO:
            ultimo_fim = max((l["quando"] for l in ls
                              if l["metodo"] == "POST" and l["rota"] in fins), default="")
            abertos = [l["quando"] for l in ls if l["metodo"] == "GET"
                       and l["rota"] == inicio and l["quando"] > ultimo_fim]
            if abertos:
                por_acabar.append({"email": email, "percurso": nome,
                                   "vezes": len(abertos), "ultima": abertos[-1]})
    return contas_, por_acabar


def _cartao_do_uso(id_):
    """O uso da aplicação na página da empresa: só o dono a vê."""
    contas_, por_acabar = uso_da_empresa(id_)
    if not contas_:
        return cartao("Uso da aplicação", "<p class='nota'>Ninguém da empresa usou a "
                      "aplicação nos últimos 30 dias.</p>", id_="uso")
    tabela = ("<table class='mg-table tab-plataforma'><thead><tr><th>Conta</th>"
              "<th>Dias com uso</th><th>Última vez</th><th>O que mais abre</th></tr>"
              "</thead><tbody>%s</tbody></table>" % "".join(
                  "<tr>%s%s%s%s</tr>" % (
                      _celula_da_tabela("Conta", html.escape(u["email"])),
                      _celula_da_tabela("Dias com uso", "%d" % u["dias"], "mg-num"),
                      _celula_da_tabela("Última vez", html.escape(data_hora_pt(u["ultima"][:16])),
                                        "mg-num"),
                      _celula_da_tabela("O que mais abre", html.escape(", ".join(u["paginas"]))))
                  for u in contas_))
    encravados = ("<div class='mg-field__label' style='margin:16px 0 6px'>Começados "
                  "e não acabados</div><ul class='ficha-lista'>%s</ul>" % "".join(
                      "<li><b>%s</b>: %s — abriu %s sem gravar, a última a %s</li>"
                      % (html.escape(p["email"]), html.escape(p["percurso"]),
                         plural(p["vezes"], "vez", "vezes"),
                         html.escape(data_hora_pt(p["ultima"][:16])))
                      for p in por_acabar)) if por_acabar else ""
    return cartao("Uso da aplicação", tabela + encravados,
                  meta="os últimos 30 dias; só tu vês", id_="uso")


def _tabela_das_visitas(titulo, cabecalhos, linhas):
    """Um cartão com uma tabela de contagens; vazio diz-se."""
    if not linhas:
        return cartao(titulo, "<p class='nota'>Nada neste período.</p>")
    return cartao(titulo, "<table class='mg-table tab-plataforma'><thead><tr>%s</tr>"
                  "</thead><tbody>%s</tbody></table>" % (
                      "".join("<th>%s</th>" % h for h in cabecalhos),
                      "".join("<tr>%s</tr>" % "".join(
                          _celula_da_tabela(h, html.escape(str(v)),
                                            "mg-num" if isinstance(v, int) else "")
                          for h, v in zip(cabecalhos, l)) for l in linhas)))


@app.route("/plataforma/visitas")
def plataforma_visitas():
    """As visitas ao site público, para o dono (ANL, 4/10/2026), com o
    período do /situacao. Só o dono (ROTAS_SO_DONO, por prefixo)."""
    periodo = request.args.get("periodo") or "mes"
    if periodo not in dict(PERIODOS_DA_SITUACAO):
        periodo = "mes"
    janela, _, _ = janelas_do_periodo(periodo, date.today())
    onde, args = ("WHERE dia BETWEEN ? AND ?", list(janela)) if janela else ("", [])
    with liga() as c:
        def um(sql, mais=()):
            return c.execute(sql % onde, args + list(mais)).fetchall()
        total, com_js, eventos = um(
            "SELECT COUNT(*), SUM(com_js), GROUP_CONCAT(eventos, '') FROM visitas %s")[0]
        visitantes = um("SELECT COUNT(*) FROM (SELECT DISTINCT dia, visitante "
                        "FROM visitas %s)")[0][0]
        tempos = sorted(r[0] for r in um("SELECT segundos FROM visitas %s"
                                         + (" AND" if onde else " WHERE")
                                         + " com_js=1 AND segundos > 0"))
        scroll = um("SELECT AVG(scroll) FROM visitas %s" + (" AND" if onde else " WHERE")
                    + " com_js=1")[0][0]
        paginas = um("SELECT caminho, COUNT(*) n FROM visitas %s "
                     "GROUP BY caminho ORDER BY n DESC LIMIT 20")
        origens = um("SELECT CASE origem WHEN '' THEN 'directo, ou de dentro do site' "
                     "ELSE origem END, COUNT(*) n FROM visitas %s "
                     "GROUP BY origem ORDER BY n DESC LIMIT 20")
        campanhas = um("SELECT utm_fonte, utm_meio, utm_campanha, COUNT(*) n FROM "
                       "visitas %s" + (" AND" if onde else " WHERE")
                       + " (utm_fonte != '' OR utm_campanha != '') "
                       "GROUP BY 1, 2, 3 ORDER BY n DESC LIMIT 20")
        pedidos = um("SELECT CASE v.origem WHEN '' THEN 'directo' ELSE v.origem END, "
                     "v.utm_campanha, COUNT(*) n FROM pedidos_acesso p "
                     # o `dia` só existe nas visitas
                     "JOIN visitas v ON v.id = p.vista %s GROUP BY 1, 2 ORDER BY n DESC")
    contados = Counter(e for e in (eventos or "").split("|") if e)
    mediana = tempos[len(tempos) // 2] if tempos else 0
    factos = "<div class='mg-stats'>%s%s%s%s</div>" % (
        kpi("Visitas", mil_pt(total or 0), "%s com JavaScript" % mil_pt(com_js or 0)),
        kpi("Visitantes", mil_pt(visitantes),
            "únicos em cada dia, somados (de um dia para o outro não se reconhecem)"),
        kpi("Tempo na página", "%d s" % mediana, "a mediana, das com JavaScript"),
        kpi("Até onde desceram", "%d%%" % round(scroll or 0), "a média do scroll"))
    funil = _tabela_das_visitas(
        "O que fizeram", ("Passo", "Visitas"),
        [("Visitas com JavaScript", com_js or 0)]
        + [(rotulo, contados.get(k, 0)) for k, rotulo in EVENTOS_DA_VISITA.items()])
    escolha = " · ".join(
        "<a href='?periodo=%s'%s>%s</a>" % (k, " aria-current='page'" if k == periodo
                                            else "", html.escape(v))
        for k, v in PERIODOS_DA_SITUACAO)
    corpo = ("<div class='larg' style='display:flex;flex-direction:column;gap:18px'>"
             "<p class='nota'>Período: %s</p>%s%s%s%s%s%s</div>"
             % (escolha, factos, funil,
                _tabela_das_visitas("De onde vieram", ("Origem", "Visitas"), origens),
                _tabela_das_visitas("Campanhas (utm)", ("Fonte", "Meio", "Campanha",
                                                        "Visitas"), campanhas),
                _tabela_das_visitas("Os pedidos, por origem", ("Origem", "Campanha",
                                                              "Pedidos"), pedidos),
                _tabela_das_visitas("Páginas", ("Página", "Visitas"), paginas)))
    return envolver(
        "configuracoes", "Visitas ao site", "", corpo, titulo_aba="Visitas · Plataforma",
        cabeca=cabecalho_de_pagina(
            "Visitas ao site",
            "Sem cookies e sem guardar o IP: os robôs, quem tem sessão e este PC "
            "não contam. Guardam-se %d meses." % MESES_DAS_VISITAS,
            [("Plataforma", "/plataforma"), ("Visitas ao site", "")]))


def _do_site(texto):
    """As marcas que o site e as páginas legais levam, preenchidas: a
    moldura (tokens, tema, letra), o topo e o rodapé, as ligações legais
    (F8, só com o operador preenchido), e os números do site."""
    moldura = ""
    try:
        with open(os.path.join(os.path.dirname(SITE), "moldura.css"),
                  encoding="utf-8") as f:
            moldura = f.read()
    except OSError:
        pass
    legal = operador_completo()
    for marca_, valor in (
            ("<!--MOLDURA-->", TEMA_DO_SISTEMA_JS + PRE_CARGA_DAS_LETRAS
             + "<style>%s%s</style>" % (TOKENS_DO_SITE, moldura)),
            ("<!--TOPO-->", TOPO_DAS_PAGINAS_DO_SITE),
            ("<!--RODAPE-->", RODAPE_DO_SITE),
            ("<!--OLHO-->", _olho_do_site("")),
            ("<!--LEGAL-->", " · <a href=\"/termos\">Termos</a> · "
             "<a href=\"/privacidade\">Privacidade</a>" if legal else ""),
            ("<!--LEGAL-NOTA-->", " — ver a <a href=\"/privacidade\">política de "
             "privacidade</a>" if legal else "")):
        texto = texto.replace(marca_, valor)
    if "<!--FAQ-JSONLD-->" in texto:
        texto = texto.replace("<!--FAQ-JSONLD-->", faq_em_json_ld(texto))
    texto = datas_do_exemplo(texto)
    if "<!--ROSTO-->" in texto:
        texto = texto.replace("<!--ROSTO-->", rosto_do_site())
    if "{{CONCURSOS}}" in texto:
        n = concursos_na_base()
        if n is None:
            # sem base, a caixa do número sai; nunca um número inventado
            texto = re.sub(r"<li>(?:(?!</li>).)*\{\{CONCURSOS\}\}.*?</li>", "",
                           texto, flags=re.S)
        else:
            texto = texto.replace("{{CONCURSOS}}", numero_do_site(n))
    # Com sessão, o topo não convida a entrar nem a pedir acesso (5.ª
    # ronda): volta à aplicação, no aspecto da conta
    if com_sessao():
        texto = com_o_tema_da_conta(texto.replace(
            '<a class="entrar" href="/entrar">Entrar</a><a class="btn btn-claro '
            'btn-pequeno" href="/#acesso">Pedir acesso</a>',
            '<a class="btn btn-claro btn-pequeno" href="/">Voltar ao Mira Gov</a>'))
    if "{{RITMO}}" in texto:
        ritmo, detalhe = ritmo_da_verificacao(
            ler_config().get("horas_verificacao") or [])
        texto = texto.replace("{{RITMO}}", ritmo).replace(
            "{{RITMO_DETALHE}}", detalhe)
    return _com_o_beacon(texto)


def pagina_do_site():
    """O site, ou None se o ficheiro faltar -- e entao a porta manda ao
    login, como antes. Le-se a cada pedido: sao 50 KB, e assim mudar o
    texto nao pede reiniciar o painel."""
    try:
        with open(SITE, encoding="utf-8") as f:
            texto = f.read()
    except OSError:
        return None
    return Response(_do_site(texto), mimetype="text/html")


def pagina_legal(qual):
    """Os termos ou a politica de privacidade (F8), com os dados do
    operador. None enquanto o operador nao estiver preenchido: uma
    politica de privacidade sem responsavel nao se publica."""
    op = operador_completo()
    if not op:
        return None
    try:
        with open(os.path.join(os.path.dirname(SITE), qual + ".html"),
                  encoding="utf-8") as f:
            texto = f.read()
    except OSError:
        return None
    nif = (op.get("nif") or "").strip()
    texto = texto.replace("{{NIF}}", ", NIF " + html.escape(nif) if nif else "")
    for marca_, chave in (("{{NOME}}", "nome"), ("{{MORADA}}", "morada")):
        texto = texto.replace(marca_, html.escape(op[chave].strip()))
    return Response(_do_site(texto), mimetype="text/html")


