def _avisar_do_pedido(id_, p):
    """O e-mail ao dono, em fundo: o envio espera ate 30 s pelo servidor
    de correio, e o visitante nao tem de esperar por isso. O que o envio
    responder fica na linha do pedido -- sem palavra-passe configurada
    o pedido fica guardado na mesma, e a pagina dos pedidos di-lo."""
    corpo = ("Pedido de acesso ao Mira Gov\n\n"
             "Nome: %(nome)s\nEmpresa: %(empresa)s\n"
             "E-mail: %(email)s\nTelemóvel: %(telefone)s\nÁrea: %(sector)s\n"
             % dict({"telefone": "—"}, **p))
    # Para o endereco dos avisos da PLATAFORMA (26/09/2026). Ia para o
    # `para` da empresa activa -- a 1, numa thread sem pedido --, que
    # numa plataforma sem empresas nao existe, e com clientes e o e-mail
    # de um cliente: os dados de quem pediu acesso iam parar-lhe.
    try:
        _, resposta = enviar_email("Mira Gov: pedido de acesso de %s"
                                   % p["empresa"], corpo, config_do_correio())
    except Exception as erro:              # nunca derruba a thread
        resposta = "%s: %s" % (type(erro).__name__, str(erro)[:120])
    with liga() as c:
        c.execute("UPDATE pedidos_acesso SET avisado=? WHERE id=?",
                  (resposta, id_))


def ip_de_quem_pede():
    """O IP para um tecto de uma rota aberta: o que a Cloudflare escreve.
    O `remote_addr` vem do X-Forwarded-For pelo ProxyFix, e esse o
    visitante pode mandar feito (revisao de seguranca de 23/09/2026)."""
    return (request.headers.get("Cf-Connecting-Ip") or request.remote_addr
            or "")[:64]


@app.route("/pedir-acesso", methods=["POST"])
def pedir_acesso():
    """O formulario do site. **A guarda e esta**, porque a rota e aberta
    e sai da porta antes da guarda do POST (ver `ROTAS_ABERTAS`):

    - a origem tem de ser daqui (`origem_e_nossa()`);
    - o campo-armadilha `website`, que uma pessoa nao ve, tem de vir
      vazio -- se vier cheio responde-se que correu bem e nao se grava
      nada, para o robo nao aprender a contorna-lo;
    - os campos validam-se e cortam-se no tamanho;
    - e ha tecto por IP e por dia.

    Responde JSON a quem o pede (o `fetch` do site) e uma pagina a quem
    nao tem JavaScript."""
    quer_json = pede_json()

    def resposta(ok, erro="", codigo=200, estado=""):
        if quer_json:
            return Response(json.dumps(dict({"ok": ok, "erro": erro},
                                            **({"estado": estado} if estado else {}))),
                            codigo, mimetype="application/json")
        if ok:
            # Post/Redirect/Get (5.ª ronda): o 200 ao POST fazia o F5 voltar
            # a mandar o pedido, e foi assim que nasceu um terceiro. Desde a
            # 6.ª ronda vai para a página de estado do pedido.
            return redirect(estado or "/pedido-recebido", 303)
        # quem pede não tem conta: o botão volta ao formulário (4.ª ronda:
        # dizia «Voltar ao Hoje»)
        # e o formulário volta ali mesmo, com o que se escreveu (5.ª
        # ronda: sem JavaScript, o erro obrigava a escrever tudo de novo)
        return Response((PAGINA_ERRO % {"css": LIGACAO_CSS,
                                        "titulo": "Falta corrigir o pedido",
                                        "texto": html.escape(erro),
                                        "logo": logotipo(tamanho=24)}).replace(
                            ACCAO_DA_PAGINA_DE_ERRO, _formulario_do_pedido_outra_vez()),
                        codigo, mimetype="text/html")

    if not origem_e_nossa():
        return resposta(False, "Pedido recusado: vem de outro sítio.", 403)
    f = request.form
    if (f.get("website") or "").strip():
        return resposta(True)
    # Só o nome, a empresa, o e-mail, o telemóvel e a área (4/10/2026,
    # decisão dele): o NIF e o plano obrigatórios faziam desistir quem só
    # queria experimentar. O plano escolhe-o o dono ao aceitar. Uma
    # página antiga, em cache, que ainda mande o NIF, o plano ou a
    # mensagem, vê-os guardados.
    p = {chave: " ".join((f.get(chave) or "").split())[:tecto]
         for chave, tecto in (("nome", 120), ("empresa", 160),
                              ("email", 200), ("sector", 60), ("telefone", 30))}
    p["mensagem"] = (f.get("mensagem") or "").strip()[:2000]
    # cortado a 200 e só depois conferido, um e-mail comprido ficava
    # outro e-mail válido (4/10/2026)
    if len(" ".join((f.get("email") or "").split())) > 200:
        return resposta(False, "O e-mail tem mais de 200 caracteres. "
                               "Confira-o.", 400)
    p["nif"] = nif_do_pedido(f.get("nif"))
    p["plano"] = f.get("plano") if f.get("plano") in PLANOS_DO_PEDIDO else ""
    vista = f.get("vista") if RX_ID_DA_VISITA.fullmatch(f.get("vista") or "") else ""
    telefone_bom = telefone_valido(p["telefone"])
    if telefone_bom:
        p["telefone"] = telefone_arrumado(p["telefone"])
    if not (p["nome"] and p["empresa"] and RX_EMAIL.fullmatch(p["email"])
            and telefone_bom and p["sector"] in SECTORES_DO_PEDIDO + SECTORES_ANTIGOS):
        completo = (p["nome"] and p["empresa"] and p["email"] and p["telefone"]
                    and p["sector"] in SECTORES_DO_PEDIDO + SECTORES_ANTIGOS)
        # só o campo mal escrito diz-se como tal (3.ª ronda, G103)
        if completo and not RX_EMAIL.fullmatch(p["email"]):
            return resposta(False, "O e-mail não parece válido. Confira-o: "
                                   "é para lá que respondemos.", 400)
        if completo:
            return resposta(False, "O telemóvel não parece válido: são nove "
                                   "algarismos, ou o indicativo e o número.", 400)
        return resposta(False, "Preencha o nome, a empresa, um e-mail válido, "
                               "o telemóvel e a área, para podermos responder.", 400)
    agora = datetime.now()
    ip = ip_de_quem_pede()
    with liga() as c:
        do_ip = c.execute(
            "SELECT COUNT(*) n FROM pedidos_acesso WHERE ip=? AND criado_em>=?",
            (ip, (agora - timedelta(hours=1)).isoformat(" ", "seconds"))
        ).fetchone()["n"]
        do_dia = c.execute(
            "SELECT COUNT(*) n FROM pedidos_acesso WHERE criado_em>=?",
            (agora.strftime("%Y-%m-%d"),)).fetchone()["n"]
        do_email = c.execute(
            "SELECT COUNT(*) n FROM pedidos_acesso WHERE lower(email)=? "
            "AND criado_em>=?", (p["email"].lower(), agora.strftime("%Y-%m-%d"))
        ).fetchone()["n"]
        if (do_ip >= PEDIDOS_POR_IP_POR_HORA or do_dia >= PEDIDOS_POR_DIA
                or do_email >= PEDIDOS_POR_EMAIL_POR_DIA):
            return resposta(False, "Recebemos muitos pedidos agora. Tente "
                                   "de novo mais tarde.", 429)
        # a página de estado do pedido (6.ª ronda): o código só vai para
        # quem pediu; na base fica o resumo
        codigo_do_pedido = secrets.token_urlsafe(18)
        id_ = c.execute(
            "INSERT INTO pedidos_acesso (criado_em, nome, empresa, email, "
            "sector, mensagem, ip, nif, plano, telefone, vista, codigo) "
            "VALUES (?,?,?,?,?,?,?,?,?,?,?,?)",
            (agora.isoformat(" ", "seconds"), p["nome"], p["empresa"],
             p["email"], p["sector"], p["mensagem"], ip, p["nif"],
             p["plano"], p["telefone"], vista,
             _resumo_do_codigo(codigo_do_pedido))).lastrowid
    # de onde veio quem pediu (ANL): a visita que o beacon pôs no formulário
    marcar_evento_da_visita(vista, ["enviado"])
    threading.Thread(target=_avisar_do_pedido, args=(id_, p),
                     daemon=True).start()
    return resposta(True, estado="/pedido/" + codigo_do_pedido)


def _resumo_do_codigo(codigo):
    return hashlib.sha256((codigo or "").encode("utf-8")).hexdigest()


# O que a página de estado diz em cada estado do pedido (6.ª ronda,
# 5/10/2026): quem pedia não tinha onde ver se fora aceite, e pedia outra
# vez. O recusado não leva o motivo, como o e-mail da recusa.
ESTADO_DO_PEDIDO = {
    "": ("Recebemos o seu pedido",
         "Estamos a vê-lo. Respondemos para o e-mail que indicou, normalmente "
         "no próprio dia útil."),
    "espera": ("O seu pedido está em lista de espera",
               "Os lugares de fundador estão ocupados por agora. Avisamos por "
               "e-mail quando abrir um, e não precisa de pedir outra vez."),
    "aceite": ("O seu pedido foi aceite",
               "Enviámos o convite para criar a conta para %s. Se não o "
               "encontrar, veja também no correio indesejado, ou escreva para "
               "<a href='mailto:contacto@miragov.pt'>contacto@miragov.pt</a>."),
    "recusado": ("Não pudemos aceitar o pedido",
                 "Obrigado pelo interesse. Se achar que foi engano, escreva para "
                 "<a href='mailto:contacto@miragov.pt'>contacto@miragov.pt</a>."),
}


@app.route("/pedido/<codigo>")
def estado_do_pedido(codigo):
    """A página de estado do pedido (rota aberta: a guarda é o código, que
    só quem pediu tem, como no convite). Um código que não existe dá 404,
    sem dizer mais nada."""
    with liga() as c:
        p = c.execute("SELECT estado, email FROM pedidos_acesso WHERE codigo=?",
                      (_resumo_do_codigo(codigo),)).fetchone() if codigo else None
    if not p:
        abort(404)
    titulo, texto = ESTADO_DO_PEDIDO.get(p["estado"] or "", ESTADO_DO_PEDIDO[""])
    if "%s" in texto:
        texto = texto % "<b>%s</b>" % html.escape(p["email"] or "o seu e-mail")
    return Response((PAGINA_ERRO % {"css": LIGACAO_CSS, "titulo": html.escape(titulo),
                                    "texto": texto, "logo": logotipo(tamanho=24)}).replace(
                        ACCAO_DA_PAGINA_DE_ERRO,
                        '<a class="mg-btn mg-btn--primary" href="/">Voltar ao site</a>'),
                    mimetype="text/html", headers={"Cache-Control": "no-store"})


def _formulario_do_pedido_outra_vez():
    """O formulário do pedido com o que veio, para corrigir sem JavaScript
    (o CSRF não se aplica: a rota é aberta e tem a guarda dentro)."""
    f = request.form

    def campo(nome, rotulo, tipo="text"):
        return ("<div class='mg-field'><label class='mg-field__label' for='p-%s'>%s"
                "</label><input class='mg-field__input' id='p-%s' name='%s' type='%s' "
                "value='%s' required></div>"
                % (nome, rotulo, nome, nome, tipo,
                   html.escape((f.get(nome) or "")[:200], quote=True)))
    opcoes = "".join("<option%s>%s</option>" % (
        " selected" if f.get("sector") == o else "", html.escape(o))
        for o in SECTORES_DO_PEDIDO)
    return ("<form method='post' action='/pedir-acesso' style='text-align:left'>%s%s%s%s"
            "<div class='mg-field'><label class='mg-field__label' for='p-sector'>Área"
            "</label><select class='mg-field__input' id='p-sector' name='sector' "
            "required><option value=''>Escolher a área</option>%s</select></div>"
            "<div class='mg-field'><label class='mg-field__label' for='p-mensagem'>"
            "%s</label><textarea class='mg-field__input' id='p-mensagem' "
            "name='mensagem' maxlength='%d'>%s</textarea></div>"
            "<input type='hidden' name='plano' value='%s'>"
            "<button type='submit' class='mg-btn mg-btn--primary'>Pedir acesso</button>"
            "</form>"
            % (campo("nome", "Nome"), campo("empresa", "Empresa"),
               campo("email", "E-mail", "email"), campo("telefone", "Telemóvel", "tel"),
               opcoes, ROTULO_DO_QUE_VENDE, TECTO_DO_QUE_VENDE,
               html.escape((f.get("mensagem") or "")[:TECTO_DO_QUE_VENDE]),
               html.escape(f.get("plano") or "", quote=True)))


