@app.route("/pedidos-de-acesso")
def pedidos_de_acesso():
    """Os pedidos que o site recebeu, para o dono. Existe porque o e-mail
    pode nao chegar -- sem correio configurado, o aviso nao sai, e o
    pedido so se ve aqui. Desde 26/09/2026 (a pagina do dono): no molde
    da plataforma, em cartoes no telemovel (o «aceitar» ficava fora do
    ecra a 390px), o «aceite» leva a empresa, e um pedido recusa-se com
    o motivo, sem se apagar."""
    with liga() as c:
        linhas = c.execute("SELECT * FROM pedidos_acesso "
                           "ORDER BY id DESC LIMIT 500").fetchall()
    existem = empresas_existentes()
    apagadas = empresas_apagadas()
    # Os pedidos do mesmo e-mail (4/10/2026, decisão dele: «permite, mas
    # sinaliza»): quantos fez, e qual destes é, por ordem de chegada
    por_email = {}
    for l in sorted(linhas, key=lambda l: l["id"]):
        por_email.setdefault((l["email"] or "").strip().lower(), []).append(l["id"])

    # E a mesma pessoa noutra empresa, pelo telemóvel, e a mesma mensagem
    # noutro pedido (LANC-F, 4/10/2026: no ensaio, 8 pessoas pediram por
    # várias empresas e 18 pedidos traziam a mesma mensagem-modelo)
    def chave_tel(l):
        return re.sub(r"\D", "", l["telefone"] or "")[-9:]

    def chave_msg(l):
        return " ".join(simplifica(l["mensagem"]).split())
    def chave_empresa(l):
        return chave_do_nome_da_empresa(l["empresa"])
    empresas_do_tel, ids_do_tel, ids_da_msg, ids_da_empresa = {}, {}, {}, {}
    for l in linhas:
        if chave_tel(l):
            empresas_do_tel.setdefault(chave_tel(l), set()).add(chave_empresa(l))
            ids_do_tel.setdefault(chave_tel(l), set()).add(l["id"])
        if chave_msg(l):
            ids_da_msg.setdefault(chave_msg(l), set()).add(l["id"])
        if chave_empresa(l):
            ids_da_empresa.setdefault(chave_empresa(l), set()).add(l["id"])
    # quem já tem conta, e o que já se decidiu à mesma pessoa (6.ª ronda,
    # 5/10/2026: a colega entrou pelo convite e pediu outra vez; o recusado
    # pediu outra vez e parecia novo)
    with liga() as c:
        conta_do_email = {(r["email"] or "").strip().lower(): r["empresa_id"]
                          for r in c.execute("SELECT email, empresa_id FROM utilizadores")}

    def repetido(l):
        email = (l["email"] or "").strip().lower()
        ids = por_email.get(email, [])
        etiquetas = []
        if len(ids) >= 2:
            etiquetas.append("%d.º de %d pedidos deste e-mail"
                             % (ids.index(l["id"]) + 1, len(ids)))
        if len(empresas_do_tel.get(chave_tel(l), ())) >= 2:
            etiquetas.append("mesmo telemóvel noutra empresa")
        elif ids_do_tel.get(chave_tel(l), set()) - set(ids):
            etiquetas.append("mesmo telemóvel de outro pedido")
        if (len(ids_da_empresa.get(chave_empresa(l), ())) >= 2
                and len(ids_da_empresa[chave_empresa(l)] - set(ids)) >= 1):
            etiquetas.append("mesma empresa noutro pedido")
        if len(ids_da_msg.get(chave_msg(l), ())) >= 2:
            etiquetas.append("mesma mensagem noutro pedido")
        if email in conta_do_email:
            id_ = conta_do_email[email] or 0
            etiquetas.append("já tem conta" + (
                " (<a href='/plataforma/empresa/%d'>empresa %d</a>)" % (id_, id_)
                if id_ else ""))
        for o in linhas:
            if (o["id"] < l["id"] and o["estado"] in ("recusado", "espera")
                    and ((o["email"] or "").strip().lower() == email
                         or (chave_tel(o) and chave_tel(o) == chave_tel(l)))):
                dia_ = data_pt((o["decidido_em"] or o["criado_em"] or "")[:10])
                etiquetas.append("recusado a %s" % dia_ if o["estado"] == "recusado"
                                 else "em espera desde %s" % dia_)
                break
        return "".join(" <span class='mg-tag %s'>%s</span>" % (tom("avisa"), e)
                       for e in etiquetas)
    desde, nomes = {}, {}
    for id_ in existem:
        with com_empresa(id_):
            cfg_ = ler_config()
            desde[id_] = cfg_.get("empresa_desde") or ""
            nomes[id_] = cfg_.get("nome_da_empresa") or ""

    def outra_empresa(l, id_):
        """A empresa que lá está com esse número não é a que o pedido deu
        (G57): chegou DEPOIS da decisão, e herdou o número de uma apagada
        -- antes de os números deixarem de se reutilizar (D10)."""
        chegou = desde.get(id_) or ""
        if not chegou:
            return False
        decidido = (l["decidido_em"] or "")[:10]
        if decidido:
            return decidido < chegou
        # os aceites de antes de 29/09/2026 não guardavam o dia: o pedido
        # é anterior à empresa E o nome não é o que o pedido deu
        return ((l["criado_em"] or "")[:10] < chegou
                and simplifica(nomes.get(id_) or "")
                != simplifica(l["empresa"] or l["nome"] or ""))

    def decisao(l):
        if l["estado"] == "aceite":
            id_ = l["empresa_id"] or 0
            if id_ in existem and not outra_empresa(l, id_):
                return ("<a href='/plataforma/empresa/%d'>aceite: empresa %d</a>"
                        % (id_, id_))
            return ("aceite: empresa %d (apagada%s)"
                    % (id_, " a %s" % data_pt(apagadas[id_])
                       if id_ in apagadas else ""))
        if l["estado"] == "recusado":
            return "recusado a %s: %s" % (html.escape(data_pt((l["decidido_em"] or "")[:10])),
                                          html.escape(l["motivo"] or ""))
        return ("<div class='mg-row' style='gap:8px;flex-wrap:wrap;align-items:center'>"
                # secundario: um primario por pedido eram muitos (V8)
                "<a class='mg-btn mg-btn--sm mg-btn--secondary' "
                "href='/pedidos-de-acesso/%d/aceitar'>aceitar&hellip;</a>"
                "<form class='accao' method='post' action='/pedidos-de-acesso/%d/recusar' "
                "onsubmit=\"return confirm(%s)\" "
                "style='display:flex;gap:6px;flex-wrap:wrap;align-items:center'>"
                "<input class='mg-field__input' type='text' name='motivo' required "
                "maxlength='300' placeholder='motivo' aria-label='Motivo da recusa do "
                "pedido de %s' style='width:12em'>"
                "<label class='nota'><input type='checkbox' name='avisar' value='1'> "
                "avisar por e-mail</label>"
                "<button type='submit' class='mg-btn mg-btn--sm mg-btn--secondary'>"
                "recusar</button></form>%s</div>"
                % (l["id"], l["id"],
                   # G58: recusar não se desfaz, e não perguntava
                   html.escape(json.dumps("Recusar o pedido de %s? Fica recusado, "
                                          "com o motivo, e não se desfaz."
                                          % (l["empresa"] or l["nome"])), quote=True),
                   html.escape(l["empresa"] or l["nome"], quote=True),
                   # a lista de espera (LANC-F): o e-mail sai sozinho
                   "" if l["estado"] == "espera" else
                   "<form class='accao' method='post' action='/pedidos-de-acesso/%d/espera'>"
                   "<button type='submit' class='mg-btn mg-btn--sm mg-btn--secondary' "
                   "title='Fica na lista de espera, e quem pediu recebe um e-mail a "
                   "dizê-lo'>pôr em espera</button></form>" % l["id"]))

    def tabela(linhas):
        return ("<div class='mg-card tab-cx'><table class='mg-table tab-plataforma'>"
                 "<thead><tr><th>Quando</th><th>Nome</th><th>Empresa</th>"
                 "<th>E-mail</th><th>Telemóvel</th><th>Área</th><th>Mensagem</th>"
                 "<th>Aviso por e-mail</th><th>Decisão</th></tr></thead><tbody>%s</tbody>"
                 "</table></div>"
                 % "".join(
                     "<tr>%s%s%s%s%s%s%s%s%s</tr>" % (
                         _celula_da_tabela("Quando", html.escape(data_hora_pt(l["criado_em"])), "mg-num"),
                         _celula_da_tabela("Nome", html.escape(l["nome"])),
                         _celula_da_tabela("Empresa", html.escape(l["empresa"])),
                         _celula_da_tabela("E-mail", "<a href='mailto:%s'>%s</a>%s"
                                 % (html.escape(l["email"], quote=True), html.escape(l["email"]),
                                    repetido(l))),
                         _celula_da_tabela("Telemóvel", ("<a href='tel:%s'>%s</a>" % (
                             html.escape(re.sub(r"[^\d+]", "", l["telefone"]), quote=True),
                             html.escape(l["telefone"]))) if l["telefone"] else "—", "mg-num"),
                         _celula_da_tabela("Área", html.escape(l["sector"])),
                         _celula_da_tabela("Mensagem", html.escape(l["mensagem"] or "")),
                         _celula_da_tabela("Aviso por e-mail", html.escape(l["avisado"] or "a enviar")),
                         _celula_da_tabela("Decisão", decisao(l)))
                     for l in linhas))

    # Os por decidir em cima, num cartao seu, e os decididos por baixo
    # (UX-7-LEIS M5, 30/09/2026): estavam misturados por ordem de chegada.
    por_decidir = [l for l in linhas if not l["estado"]]
    em_espera = [l for l in linhas if l["estado"] == "espera"]
    decididos = [l for l in linhas if l["estado"] in ("aceite", "recusado")]
    def seccao(titulo, estes):
        return ("<h2 class='mg-card__title pedidos-titulo'>%s &middot; %s</h2>%s"
                % (titulo, mil_pt(len(estes)), tabela(estes)))
    if linhas:
        corpo = ((seccao("Por decidir", por_decidir) if por_decidir else
                  "<p class='nota'>Nenhum pedido por decidir.</p>")
                 + (seccao("Em espera", em_espera) if em_espera else "")
                 + (seccao("Decididos", decididos) if decididos else ""))
    else:
        corpo = ("<div class='mg-empty'>Ainda não chegou nenhum pedido pelo "
                 "site.</div>")
    return envolver(
        "configuracoes", "Pedidos de acesso", "", "<div class='larg'>%s</div>" % corpo,
        titulo_aba="Pedidos de acesso · Plataforma",
        cabeca=cabecalho_de_pagina(
            "Pedidos de acesso",
            "O que o formulário do site público recebeu. Cada pedido novo avisa o "
            "endereço dos avisos da plataforma, se o <a href='/plataforma#correio'>"
            "correio</a> estiver configurado.",
            [("Plataforma", "/plataforma"), ("Pedidos de acesso", "")]))


@app.route("/pedidos-de-acesso/<int:id_>/recusar", methods=["POST"])
def recusar_pedido(id_):
    """Recusa um pedido por decidir, com o motivo. Nao se apaga: fica na
    lista, com o dia e a razao, e nao volta a contar como «por decidir»."""
    motivo = texto_de_campo(request.form.get("motivo"), 300)
    if not motivo:
        return _volta_a("/pedidos-de-acesso", "Diga o motivo da recusa.", erro=True)
    p = _pedido_por_decidir(id_)
    if not p:
        return _volta_a("/pedidos-de-acesso", "Esse pedido já estava decidido.",
                        erro=True)
    with liga() as c:
        c.execute("UPDATE pedidos_acesso SET estado='recusado', motivo=?, "
                  "decidido_em=? WHERE id=?",
                  (motivo, datetime.now().strftime("%Y-%m-%d %H:%M"), id_))
    registar_evento("", "pedido recusado", "%s: %s" % (p["empresa"], motivo),
                    quem=quem_sou() or "")
    # avisar é escolha do dono (LANC-F): um pedido lixo não leva e-mail
    envio = ""
    if request.form.get("avisar"):
        bem, porque = responder_ao_pedido(p, "recusado")
        envio = (" Avisado por e-mail." if bem else
                 " O e-mail não saiu (%s)." % porque)
    return _volta_a("/pedidos-de-acesso", "Pedido de %s recusado.%s"
                    % (p["empresa"], envio))


def _pedido_por_decidir(id_):
    """A linha do pedido, se ainda se pode decidir (por decidir ou em
    espera); None se já foi aceite ou recusado. 404 se não existe."""
    with liga() as c:
        p = c.execute("SELECT * FROM pedidos_acesso WHERE id=?", (id_,)).fetchone()
    if not p:
        abort(404)
    return p if (p["estado"] or "") in ("", "espera") else None


@app.route("/pedidos-de-acesso/<int:id_>/espera", methods=["POST"])
def pedido_em_espera(id_):
    """Põe o pedido na lista de espera (LANC-F, 4/10/2026: as vagas, 10
    fundadores e depois ~20 empresas por semana) e avisa quem pediu.
    Continua a poder aceitar-se ou recusar-se. Só o dono (ROTAS_SO_DONO,
    por prefixo)."""
    p = _pedido_por_decidir(id_)
    if not p or p["estado"] == "espera":
        return _volta_a("/pedidos-de-acesso", "Esse pedido já não estava por decidir.",
                        erro=True)
    with liga() as c:
        c.execute("UPDATE pedidos_acesso SET estado='espera', decidido_em=? WHERE id=?",
                  (datetime.now().strftime("%Y-%m-%d %H:%M"), id_))
    registar_evento("", "pedido em espera", p["empresa"], quem=quem_sou() or "")
    bem, porque = responder_ao_pedido(p, "espera")
    return _volta_a("/pedidos-de-acesso", "Pedido de %s em espera. %s"
                    % (p["empresa"], "Avisado por e-mail." if bem else
                       "O e-mail não saiu (%s)." % porque), erro=not bem)

TEXTO_DO_CONVITE = """%(ola)s

%(frase)s

Para criar a sua conta, abra esta ligação e escolha o nome de
utilizador e a palavra-passe:

%(ligacao)s

A ligação serve uma vez e é válida até %(ate)s.

O que vem a seguir:
%(passos)s

Dúvidas? Responda a este e-mail.

Mira Gov
"""

# O que o convidado faz depois de criar a conta (29/09/2026): o e-mail
# dizia só «abra a ligação», e o gestor chegava sem saber por onde ia.
PASSOS_DO_CONVITE = {
    "admin": ("Criar a conta, na ligação acima.",
              "Confirmar o perfil da empresa (Configurações › Perfil da "
              "empresa): as áreas CPV, os distritos e os valores.",
              "Ligar os alertas, para receber os concursos novos por e-mail.",
              "Convidar os colegas, em Configurações › Conta."),
    "tester": ("Criar a conta, na ligação acima.",
               "Ver os concursos que já esperam pela empresa, em Concursos.",
               "Seguir as propostas da empresa, em Propostas."),
}


def texto_e_html_do_convite(ligacao, empresa, papel, nome="", pedido=False,
                            nota=""):
    """(assunto, texto, html) do convite. `pedido` é o aceite de um
    pedido de acesso; sem ele, é o convite que o dono ou o gestor criam.
    `nota` é o que o dono escreve a quem pediu (LANC-F, 4/10/2026: no
    ensaio do lançamento, 52 precisaram de um segundo e-mail)."""
    papel_ecra = papel_no_ecra(papel).lower()
    empresa = empresa or "sua empresa"
    frase = ("O seu pedido de acesso ao Mira Gov foi aceite. A sua conta é "
             "a de %s da %s." if pedido else
             "Tem um convite para entrar no Mira Gov, com uma conta de %s "
             "da %s.") % (papel_ecra, empresa)
    ate = data_pt((datetime.now() + timedelta(days=contas.DIAS_DE_CONVITE))
                  .strftime("%Y-%m-%d"))
    passos = PASSOS_DO_CONVITE.get(papel, PASSOS_DO_CONVITE["tester"])
    ola = "Olá %s," % nome if nome else "Olá,"
    texto = TEXTO_DO_CONVITE % {
        "ola": ola, "frase": frase + ("\n\n" + nota if nota else ""),
        "ligacao": ligacao, "ate": ate,
        "passos": "\n".join("%d. %s" % (i, p) for i, p in enumerate(passos, 1))}
    corpo = (
        _em_paragrafo(html.escape(ola)) + _em_paragrafo(html.escape(frase))
        + (_em_paragrafo(html.escape(nota).replace("\n", "<br>")) if nota else "")
        + _em_botao(ligacao, "Criar a conta")
        + _em_paragrafo("A ligação serve uma vez e é válida até <b>%s</b>." % ate)
        + "<p style=\"margin:18px 0 6px;font:700 11px/1.4 %s;color:%s;"
          "text-transform:uppercase;letter-spacing:.06em\">O que vem a seguir</p>"
          "<ol style=\"margin:0 0 16px;padding-left:20px\">%s</ol>"
          % (_EM_SANS, _EM_T2, "".join("<li style=\"margin:0 0 6px\">%s</li>"
                                      % html.escape(p) for p in passos)))
    return ("O seu acesso ao Mira Gov" if pedido else "Convite para o Mira Gov",
            texto,
            moldura_do_email("Convite para a %s" % empresa, _em_cartao_branco(corpo),
                             "Dúvidas? Responda a este e-mail. Se não esperava "
                             "este convite, pode ignorá-lo."))


def enviar_convite(email, ligacao, empresa, papel, nome="", pedido=False, nota=""):
    """Manda o convite para `email`, da conta da plataforma. (bem, porque);
    uma falha não derruba quem convida -- a ligação mostra-se na mesma."""
    if not email:
        return False, "sem endereço"
    return _mandar_a(email, *texto_e_html_do_convite(ligacao, empresa, papel,
                                                     nome, pedido, nota))


def _mandar_a(email, assunto, texto, em_html):
    """Um e-mail da conta da plataforma para um endereço só. (bem, porque);
    nunca rebenta -- o servidor pode responder o que quiser."""
    try:
        return enviar_email(assunto, texto,
                            _junta(dict(ler_config()), {"email": {"para": email}}),
                            em_html)
    except Exception as erro:
        return False, "%s: %s" % (type(erro).__name__, str(erro)[:120])


# O que quem pediu recebe quando o pedido não se aceita já (LANC-F,
# 4/10/2026). Texto fixo: o motivo da recusa é do dono, e não sai.
RESPOSTA_AO_PEDIDO = {
    "recusado": ("O seu pedido de acesso ao Mira Gov",
                 "Obrigado pelo interesse no Mira Gov. Neste momento não "
                 "conseguimos aceitar o seu pedido.\n\nSe a situação da sua "
                 "empresa mudar, pode voltar a pedir no site, ou responder a "
                 "este e-mail."),
    "espera": ("O seu pedido de acesso ao Mira Gov está na lista de espera",
               "Recebemos o seu pedido de acesso ao Mira Gov. Estamos a abrir "
               "por vagas, para acompanhar bem cada empresa que entra, e o seu "
               "pedido ficou na lista de espera.\n\nEscrevemos-lhe assim que "
               "houver lugar. Dúvidas? Responda a este e-mail."),
}


def responder_ao_pedido(p, estado):
    """Manda a quem pediu a resposta fixa de `estado` (RESPOSTA_AO_PEDIDO).
    (bem, porque)."""
    assunto, texto = RESPOSTA_AO_PEDIDO[estado]
    ola = "Olá %s," % p["nome"] if p["nome"] else "Olá,"
    corpo = "".join(_em_paragrafo(html.escape(x)) for x in
                    [ola] + texto.split("\n\n"))
    return _mandar_a(p["email"], assunto, "%s\n\n%s\n\nMira Gov\n" % (ola, texto),
                     moldura_do_email(assunto, _em_cartao_branco(corpo),
                                      "Responda a este e-mail se tiver dúvidas."))


TEXTO_DA_REPOSICAO = """%(ola)s

Pediram uma ligação para repor a palavra-passe da sua conta no Mira Gov
(%(conta)s). Para escolher uma nova, abra:

%(ligacao)s

A ligação serve uma vez e vale até às %(ate)s. Ao guardar a
palavra-passe nova, as sessões abertas desta conta fecham-se todas.

Se não foi você que pediu, ignore este e-mail: a palavra-passe só muda
com a ligação.

Mira Gov
"""


def texto_e_html_da_reposicao(ligacao, conta, nome="", agora=None):
    """(assunto, texto, html) do «esqueci-me» por e-mail (J7). Na moldura
    de todos os outros, com o botão, o prazo em hora e o «se não foi
    você» -- quem recebe isto sem o ter pedido tem de saber que não
    precisa de fazer nada."""
    ate = ((agora or datetime.now())
           + timedelta(hours=contas.HORAS_DE_REPOSICAO_POR_EMAIL)).strftime(
               "%H:%M de %d/%m/%Y")
    ola = "Olá %s," % nome if nome else "Olá,"
    texto = TEXTO_DA_REPOSICAO % {"ola": ola, "conta": conta,
                                  "ligacao": ligacao, "ate": ate}
    corpo = (
        _em_paragrafo(html.escape(ola))
        + _em_paragrafo("Pediram uma ligação para repor a palavra-passe da "
                        "sua conta no Mira Gov (<b>%s</b>)." % html.escape(conta))
        + _em_botao(ligacao, "Escolher a palavra-passe nova")
        + _em_paragrafo("A ligação serve uma vez e vale até às <b>%s</b>. Ao "
                        "guardar a palavra-passe nova, as sessões abertas "
                        "desta conta fecham-se todas." % ate))
    return ("Repor a palavra-passe do Mira Gov", texto,
            moldura_do_email("Repor a palavra-passe", _em_cartao_branco(corpo),
                             "Se não foi você que pediu, ignore este e-mail: "
                             "a palavra-passe só muda com a ligação."))


def _repor_por_email(email):
    """O «esqueci-me» depois da resposta, em fundo (J7): procurar a conta,
    criar a ligação, registar e mandar o e-mail. Tudo isto fora do
    pedido, e não só o envio: o envio espera até 30 s pelo servidor, e
    até a escrita da ligação na base demorava uns milissegundos só
    quando a conta existe -- um tempo de resposta que dizia quais
    existem. O que se regista diz a conta, nunca a ligação; uma falha do
    envio fica nos eventos."""
    with liga() as c:
        codigo, conta = contas.reposicao_por_email(c, email)
    if not conta:
        return
    if not codigo:
        registar_evento("", "conta", "pedida por e-mail a ligação de repor da "
                        "conta do dono (%s): recusada, repõe-se pela consola"
                        % conta["email"], quem="radar")
        return
    registar_evento("", "conta", "ligação de repor pedida por e-mail: %s"
                    % conta["email"], quem="radar")
    # vai para o endereço escrito, que casou com o utilizador ou com o
    # contacto (1/10/2026): o utilizador pode não ser um e-mail
    conta, nome, para = conta["email"], conta["nome"], conta["para"]
    ligacao = "%s/repor/%s" % (endereco_do_painel().rstrip("/"), codigo)
    assunto, texto, em_html = texto_e_html_da_reposicao(ligacao, conta, nome)
    try:
        bem, porque = enviar_email(
            assunto, texto, _junta(dict(ler_config()), {"email": {"para": para}}),
            em_html)
    except Exception as erro:              # nunca derruba a thread
        bem, porque = False, "%s: %s" % (type(erro).__name__, str(erro)[:120])
    if not bem:
        registar_evento("", "conta", "a ligação de repor de %s não saiu por "
                        "e-mail: %s" % (conta, porque), quem="radar")


# O perfil que o dono prepara ao aceitar (D13 da segunda ronda,
# 26/09/2026): o site promete «configuramos o perfil consigo», e sem
# isto a empresa nova entrava a ver 1 383 anúncios por decidir. O
# sector do formulário dá o ponto de partida; o dono afina antes de
# aceitar. Só as divisões que o sector diz sem dúvida: «Fornecimento de
# bens» ou «Prestação de serviços» não dizem de que -- ficam vazios.
CPV_DO_SECTOR = {"Obras públicas e construção": "45000000",
                 "Engenharia e projetos": "71000000",
                 "Software e informática": "72000000|48000000",
                 "Tecnologias de informação": "72000000|48000000",
                 "Limpeza, segurança e manutenção": "90910000|79710000|50700000",
                 "Espaços verdes e ambiente": "77300000|90600000",
                 "Consultoria": "79400000"}
# As regiões que quem pede escreve em vez dos distritos (LANC-F,
# 4/10/2026), pelo `DISTRITOS_POR_REGIAO`. «Centro» sozinho é quase
# sempre outra coisa («centro de saúde», «centro escolar»): só conta
# com «região» ou «zona» antes -- ou colado a outra região, «Norte e
# Centro», que marcava só o Norte (6.ª ronda, 5/10/2026).
_OUTRAS_REGIOES = r"(?:norte|lisboa|vale do tejo|alentejo|algarve)"
RX_REGIAO_NA_MENSAGEM = {
    regiao: re.compile(r"\b(?:regiao|zona) centro\b|\b%s\s*(?:,|e)\s*centro\b"
                       r"|\bcentro\s*(?:,|e)\s*%s\b" % (_OUTRAS_REGIOES, _OUTRAS_REGIOES)
                       if regiao == "Centro"
                       else r"\b%s\b" % re.escape(simplifica(regiao)))
    for regiao, _ in DISTRITOS_POR_REGIAO}
RX_CPV_NA_MENSAGEM = re.compile(r"\b(\d{8})(?:-\d)?\b")
# «CPV 909», «cpv: 4521» -- o prefixo que quem pede escreve à mão (G56 da
# 3.ª ronda): só os códigos de 8 algarismos entravam, e o ecrã dizia
# «vem do que a mensagem diz» com o campo vazio. Completa-se a 8 com
# zeros, como o `_perfil_do_formulario()` faz.
# E a lista inteira que vem a seguir (ensaio do percurso, 1/10/2026):
# «CPV 79 e 72» dava só o 79. O grupo apanha a fila de códigos ligados
# por vírgula, «e», «ou» ou barra; o `perfil_do_pedido()` parte-a.
RX_CPV_CURTO_NA_MENSAGEM = re.compile(
    r"\bcpvs?\s*[:n.º°o]*\s*(\d{2,8}(?:-\d)?"
    r"(?:\s*(?:,|;|/|\be\b|\bou\b)\s*\d{2,8}(?:-\d)?)*)", re.I)


def perfil_do_pedido(p):
    """(cpv, distritos) sugeridos para a empresa de um pedido: os CPV do
    sector mais os códigos de 8 dígitos escritos na mensagem, e os
    distritos que a mensagem nomeia. É um ponto de partida: o dono vê-o
    e muda-o antes de aceitar."""
    mensagem = p["mensagem"] or ""
    cpv = [c for c in (CPV_DO_SECTOR.get(p["sector"] or "") or "").split("|") if c]
    cpv += [c for c in RX_CPV_NA_MENSAGEM.findall(mensagem) if c not in cpv]
    for fila in RX_CPV_CURTO_NA_MENSAGEM.findall(mensagem):
        # os de 8 já vieram pelo de cima; o «-5» do dígito de controlo
        # não chega aos dois algarismos
        cpv += [c.ljust(8, "0") for c in re.findall(r"\d+", fila)
                if 2 <= len(c) < 8 and c.ljust(8, "0") not in cpv]
    simples = simplifica(mensagem)
    das_regioes = {d for regiao, ds in DISTRITOS_POR_REGIAO
                   if RX_REGIAO_NA_MENSAGEM[regiao].search(simples) for d in ds}
    distritos = [d for d in DISTRITOS if d in das_regioes
                 or re.search(r"\b%s\b" % re.escape(simplifica(d)), simples)]
    return "|".join(cpv), "|".join(distritos)


def _perfil_do_formulario(form):
    """O perfil que veio no formulário do aceitar, já validado, ou
    ValueError com a frase para o ecrã. Os CPV só como códigos: é o que
    a árvore grava, e um termo solto aqui apanhava o que calhasse."""
    cpv = [c.strip() for c in re.split(r"[|,;\s]+", form.get("cpv") or "") if c.strip()]
    maus = [c for c in cpv if not re.fullmatch(r"\d{2,8}", c)]
    if maus:
        raise ValueError("«%s» não é um código CPV (só algarismos, ex. 45000000)."
                         % corta(maus[0], 20))
    pbmin = (form.get("pbmin") or "").strip()
    if recado_do_preco(pbmin):
        raise ValueError(recado_do_preco(pbmin))
    distritos = [d for d in form.getlist("dist") if d in DISTRITOS]
    return {"interesse_activo": bool(cpv or distritos or pbmin),
            "interesse_cpv": "|".join(c.ljust(8, "0") for c in cpv),
            "interesse_cpv_excl": "",
            "interesse_distritos": "|".join(distritos),
            "interesse_pbmin": pbmin}


def _formulario_do_aceitar(p, aviso=""):
    """O passo antes de aceitar: quem pediu, o que escreveu, e o perfil
    da empresa nova pré-preenchido, para o dono o afinar."""
    cpv, distritos = perfil_do_pedido(p)
    if request.method == "POST":           # volta com o que se escreveu
        cpv = request.form.get("cpv") or ""
        distritos = "|".join(request.form.getlist("dist"))
    caixas = caixas_dos_distritos(set(distritos.split("|")))
    return envolver(
        "configuracoes", "Aceitar o pedido",
        "Cria a empresa, prepara o perfil dela e manda o convite a quem pediu.",
        "<div class='larg'>%s<div class='mg-card conf-cx'>"
        "<p><b>%s</b>, de %s &middot; <a href='mailto:%s'>%s</a>%s<br>"
        "Área: %s</p>%s</div>"
        "<form method='post' class='mg-card conf-cx conf-form'>%s"
        "<div class='mg-field__label' style='flex:1 1 100%%'>O perfil da "
        "empresa nova <span class='nota'>(só para uma empresa nova)</span></div>"
        "<p class='nota' style='flex:1 1 100%%'>O site promete «configuramos o "
        "perfil consigo». %s; afine-o antes "
        "de aceitar, ou deixe-o vazio e a empresa define-o depois.</p>"
        "%s"
        "<fieldset class='dist-interesse' style='flex:1 1 100%%'><legend>"
        "Distritos do local de execução <span class='nota'>(nenhum marcado = "
        "todos)</span></legend>%s</fieldset>"
        "%s%s"
        "<label class='mg-field' style='flex:1 1 100%%'><span class='mg-field__label'>"
        "Nota para quem pediu <span class='nota'>(opcional; vai no e-mail do "
        "convite)</span></span><textarea class='mg-field__input' name='nota' "
        "maxlength='%d'>%s</textarea></label>"
        "<div style='flex:1 1 100%%;display:flex;gap:8px'>"
        "<button type='submit' class='mg-btn mg-btn--primary'>Aceitar e "
        "mandar o convite</button>"
        "<a class='mg-btn mg-btn--secondary' href='/pedidos-de-acesso'>voltar "
        "sem aceitar</a></div></form></div>"
        % (("<div class='mg-alert mg-alert--danger' role='alert'>%s</div>"
            % html.escape(aviso)) if aviso else "",
           html.escape(p["nome"]), html.escape(p["empresa"]),
           html.escape(p["email"], quote=True), html.escape(p["email"]),
           (" &middot; %s" % html.escape(p["telefone"])) if p["telefone"] else "",
           html.escape(p["sector"] or "—"),
           ("<p class='nota'>«%s»</p>" % html.escape(p["mensagem"]))
           if p["mensagem"] else "",
           _escolha_da_empresa(p),
           "Vem do sector e do que a mensagem diz" if (cpv or distritos)
           else "O sector e a mensagem não chegaram para o sugerir: escreva-o",
           _campo("CPV", "cpv", cpv, nota="códigos separados por «|», ex. "
                  "45000000|71000000; afina-se depois na árvore, em "
                  "Configurações › Perfil da empresa"),
           caixas,
           _campo("Preço base a partir de", "pbmin",
                  request.form.get("pbmin", "") if request.method == "POST" else "",
                  nota="€; vazio = qualquer valor", extra="inputmode='decimal'"),
           _escolha_do_plano(request.form.get("plano") if request.method == "POST"
                             else p["plano"] or "fundador"),
           TECTO_DA_NOTA_DO_CONVITE,
           html.escape(request.form.get("nota", "") if request.method == "POST" else "")),
        titulo_aba="Aceitar o pedido")


TECTO_DA_NOTA_DO_CONVITE = 1000


def _escolha_do_plano(escolhido):
    """O plano com que a empresa nasce, que o dono escolhe ao aceitar: o
    formulário do site deixou de o pedir (4/10/2026)."""
    return ("<label class='mg-field' style='flex:1 1 100%%'><span class='mg-field__label'>"
            "Plano</span><select class='mg-field__input' name='plano'>%s</select></label>"
            % "".join("<option value='%s'%s>%s</option>" % (
                k, " selected" if k == escolhido else "", html.escape(v))
                for k, v in PLANOS_DO_PEDIDO.items()))


def chave_do_nome_da_empresa(nome):
    """O nome sem a forma jurídica nem a pontuação: «Obras Rápidas, Lda.»
    e «Obras Rapidas» são a mesma empresa (6.ª ronda, 5/10/2026)."""
    nome = re.sub(r"[^a-z0-9]+", " ", simplifica(nome or "").lower())
    return " ".join(re.sub(r"\b(?:lda|limitada|unipessoal|s a|sa)\b", " ",
                           nome).split())


def _empresas_para_juntar():
    """[(id, nome)] das empresas que existem, para o «juntar» do aceitar."""
    nomes = []
    for id_ in empresas_existentes():
        with com_empresa(id_):
            nomes.append((id_, ler_config().get("nome_da_empresa") or "empresa %d" % id_))
    return nomes


def _escolha_da_empresa(p):
    """Criar uma empresa nova ou juntar a pessoa a uma que já existe (6.ª
    ronda: a colega da mesma empresa só podia nascer noutra empresa). A
    que tem o mesmo nome vem escolhida."""
    juntar = request.method == "POST" and request.form.get("destino") == "juntar"
    escolhida = request.form.get("empresa_id", "") if juntar else ""
    opcoes = []
    for id_, nome in _empresas_para_juntar():
        if not escolhida and chave_do_nome_da_empresa(nome) == \
                chave_do_nome_da_empresa(p["empresa"]):
            escolhida, juntar = str(id_), juntar or request.method == "GET"
        opcoes.append("<option value='%d'%s>%s (empresa %d)</option>"
                      % (id_, " selected" if str(id_) == escolhida else "",
                         html.escape(nome), id_))
    if not opcoes:
        return ""
    return ("<fieldset style='flex:1 1 100%%'><legend class='mg-field__label'>"
            "Para onde vai quem pediu</legend>"
            "<label><input type='radio' name='destino' value='nova'%s> uma "
            "empresa nova, com o perfil e o plano de baixo</label><br>"
            "<label><input type='radio' name='destino' value='juntar'%s> juntar "
            "a uma empresa que já existe, como membro:</label> "
            "<select class='mg-field__input' name='empresa_id' "
            "aria-label='A empresa'>%s</select></fieldset>"
            % ("" if juntar else " checked", " checked" if juntar else "",
               "".join(opcoes)))


def _juntar_pedido(p):
    """O «aceitar» que junta a pessoa a uma empresa que já existe: não
    cria empresa nem mexe no perfil (é o dela), e o convite é de
    utilizador -- quem é gestor decide-o o gestor. O plano conta."""
    try:
        empresa_id = int(request.form.get("empresa_id") or "")
    except ValueError:
        empresa_id = 0
    if empresa_id not in empresas_existentes():
        return _formulario_do_aceitar(p, "Escolha a empresa da lista.")
    with liga() as c:
        if contas.lugares_livres(c, empresa_id) == 0:
            return _formulario_do_aceitar(p, contas.frase_do_limite(c, empresa_id))
        codigo = contas.criar_convite(c, empresa_id, p["email"], "tester", p["id"])
        c.execute("UPDATE pedidos_acesso SET estado='aceite', empresa_id=?, "
                  "decidido_em=? WHERE id=?",
                  (empresa_id, datetime.now().strftime("%Y-%m-%d %H:%M:%S"), p["id"]))
    with com_empresa(empresa_id):
        nome = ler_config().get("nome_da_empresa") or p["empresa"]
    registar_evento("", "pedido aceite", "%s (junta à empresa %d)"
                    % (p["empresa"], empresa_id))
    return _pedido_aceite(p, empresa_id, nome, codigo, "tester",
                          "Juntou-se à empresa %d, %s." % (empresa_id, html.escape(nome)),
                          "Junta-se à empresa n.º %d" % empresa_id,
                          "<p>O perfil e o plano são os da empresa: não mudaram.</p>")


def _pedido_aceite(p, empresa_id, nome, codigo, papel, titulo, destaque, sobre):
    """O ecrã depois de aceitar: manda o convite e mostra a ligação, que
    serve se o e-mail não sair -- e a nota com ela, que de outro modo ia
    só no e-mail (6.ª ronda, 5/10/2026)."""
    ligacao = endereco_do_painel() + "/convite/" + codigo
    nota = (request.form.get("nota") or "").strip()[:TECTO_DA_NOTA_DO_CONVITE]
    bem, porque = enviar_convite(p["email"], ligacao, nome, papel, p["nome"],
                                 pedido=True, nota=nota)
    envio = ("O convite foi enviado para <b>%s</b>." % html.escape(p["email"])
             if bem else "<b>O e-mail não saiu</b> (%s). Mande-lhe a "
             "ligação%s." % (html.escape(porque or "sem razão"),
                             ", com a nota que escreveu: «%s»" % html.escape(nota)
                             if nota else ""))
    return envolver(
        "configuracoes", "Pedido aceite", titulo,
        # o número e a ligação no corpo (G56 da 3.ª ronda): o subtítulo
        # passava despercebido, e confirmar a empresa era voltar à lista
        "<div class='larg'><div class='mg-card conf-cx'><p><b>%s</b> &mdash; "
        "<a href='/plataforma/empresa/%d'>abrir a página dela</a>.</p><p>%s</p>%s"
        "<p>A ligação, que serve uma vez e dura %d dias:</p>"
        "%s<p><a href='/pedidos-de-acesso'>voltar aos "
        "pedidos</a></p></div></div>"
        % (destaque, empresa_id, envio, sobre, contas.DIAS_DE_CONVITE,
           caixa_de_copiar(ligacao, "Ligação do convite")))


@app.route("/pedidos-de-acesso/<int:id_>/aceitar", methods=["GET", "POST"])
def aceitar_pedido(id_):
    """F5: do pedido do site a empresa a trabalhar. Cria a empresa, com o
    resumo a ir para quem pediu; cria o convite; manda-o por e-mail. E
    mostra a ligacao ao dono tambem -- o e-mail pode nao sair (sem
    palavra-passe configurada, ou recusado), e a ligacao e a unica
    coisa que a pessoa precisa. So o dono aqui chega (ROTAS_SO_DONO,
    por prefixo)."""
    with liga() as c:
        p = c.execute("SELECT * FROM pedidos_acesso WHERE id=?", (id_,)).fetchone()
    if not p:
        return redirect("/pedidos-de-acesso")
    if p["estado"] == "recusado":
        return _volta_a("/pedidos-de-acesso", "Esse pedido foi recusado.", erro=True)
    if p["estado"] == "aceite":
        return envolver("configuracoes", "Pedido já aceite",
                        "Este pedido já deu a empresa %d." % p["empresa_id"],
                        "<div class='larg'><a href='/pedidos-de-acesso'>voltar "
                        "aos pedidos</a></div>")
    if request.method == "GET":
        return _formulario_do_aceitar(p)
    if request.form.get("destino") == "juntar":
        return _juntar_pedido(p)
    try:
        perfil = _perfil_do_formulario(request.form)
    except ValueError as erro:
        return _formulario_do_aceitar(p, str(erro))
    # um plano que não é da lista criava a empresa sem plano, calado
    if (request.form.get("plano") or "") not in ("",) + tuple(PLANO_DO_PEDIDO):
        return _formulario_do_aceitar(p, "Escolha o plano da lista.")
    empresa_id = criar_empresa(p["empresa"] or p["nome"])
    with com_empresa(empresa_id):
        gravar_config(dict(perfil, email={"para": p["email"]},
                           **({"nif_da_empresa": p["nif"]} if p["nif"] else {})))
    with liga() as c:
        # o plano que o dono escolheu ao aceitar (desde 4/10/2026; ate ai
        # vinha do formulario do site); a oferta de fundador e o Duo a
        # preco de fundador.
        plano = PLANO_DO_PEDIDO.get(request.form.get("plano") or p["plano"] or "")
        if plano:
            contas.gravar_plano(c, empresa_id, plano[0], fundador=plano[1])
        codigo = contas.criar_convite(c, empresa_id, p["email"], "admin", id_)
        # o dia da decisão também no aceite (G57): é por ele que a lista
        # dos pedidos sabe se a empresa com este número ainda é a deste
        c.execute("UPDATE pedidos_acesso SET estado='aceite', empresa_id=?, "
                  "decidido_em=? WHERE id=?",
                  (empresa_id, datetime.now().strftime("%Y-%m-%d %H:%M:%S"), id_))
    registar_evento("", "pedido aceite", "%s (empresa %d)"
                    % (p["empresa"], empresa_id))
    return _pedido_aceite(
        p, empresa_id, p["empresa"], codigo, "admin",
        "A empresa %d, %s, foi criada." % (empresa_id, html.escape(p["empresa"])),
        "Empresa n.º %d criada" % empresa_id,
        "<p>%s</p>" % (("Perfil da empresa: %s." % descricao_do_interesse(perfil))
                       if perfil["interesse_activo"] else
                       "Sem perfil: a empresa define-o no primeiro dia."))


